comms.text:
@1 וּנְפַק יַעֲקֹב מִבְּאֵרָא דְשָׁבַע וַאֲזַל לְחָרָן:
@2 וַעֲרַע בְּאַתְרָא וּבָת תַּמָּן אֲרֵי עָל שִׁמְשָׁא וּנְסִיב מֵאַבְנֵי אַתְרָא וְשַׁוִּי אִסָדוֹהִי וּשְׁכִיב בְּאַתְרָא הַהוּא:
@3 וַחֲלַם וְהָא סֻלְמָא נָעִיץ בְּאַרְעָא וְרֵישֵׁהּ מָטֵי עַד צֵית שְׁמַיָּא וְהָא מַלְאָכַיָּא דַּיְיָ סָלְקִין וְנָחֲתִין בֵּהּ:
@4 וְהָא יְקָרָא דַיְיָ מְעַתַּד עִלָווֹהִי וַאֲמַר אֲנָא יְיָ אֱלָהֵהּ דְּאַבְרָהָם אָבוּךְ וֵאלָהֵהּ דְּיִצְחָק אַרְעָא דִּי אַתְּ שְׁכִיב עֲלַהּ לָךְ אֶתְּנִנַּהּ וְלִבְנָיךְ:
@5 וִיהוֹן בְּנָיךְ סַגִּיאִין כְּעַפְרָא דְאַרְעָא וְתִתְקֵף לְמַעַרְבָא וּלְמַדִינְחָא וּלְצִפּוּנָא וּלְדָרוֹמָא וְיִתְבָּרְכוּן בְּדִילָךְ כָּל זַרְעֲיַת אַרְעָא וּבְדִיל בְּנָיךְ:
@6 וְהָא מֵימְרִי בְּסַעְדָךְ וְאֶטְרִנָךְ בְּכָל אֲתַר דִּי תְהַךְ וַאֲתֵיבִנָּךְ לְאַרְעָא הָדָא אֲרֵי לָא אֶשְׁבְּקִנָּךְ עַד דִּי אֶעְבֵּיד יָת דִּי מַלֵּלִית לָךְ:
@7 וְאִתְּעַר יַעֲקֹב מִשִּׁנְתֵּהּ וַאֲמַר בְּקוּשְׁטָּא (אִית) יְקָרָא דַיְיָ שָׁרֵי בְּאַתְרָא הָדֵין וַאֲנָא לָא הֲוֵיתִי יְדָע:
@8 וּדְחִיל וַאֲמַר מָה דְחִילוּ אַתְרָא הָדֵין לֵית דֵּין אֲתַר הֶדְיוֹט אֶלָהֵין אֲתַר דְּרַעֲוָא בֵהּ מִן קֳדָם יְיָ וְדֵין תְּרַע קֳבֵל שְׁמַיָּא:
@9 וְאַקְדֵים יַעֲקֹב בְּצַפְרָא וּנְסִיב יָת אַבְנָא דִי שַׁוִּי אִסָדוֹהִי וְשַׁוִּי יָתַהּ קָמָא וַאֲרִיק מִשְׁחָא עַל רֵישֵׁהּ:
@10 וּקְרָא יָת שְׁמָא דְאַתְרָא הַהוּא בֵּית אֵל וּבְרַם לוּז שְׁמָא דְקַרְתָּא בְּקַדְמֵיתָא:
@11 וְקַיִּים יַעֲקֹב קְיָם לְמֵימָר אִם יְהֵא מֵימְרָא דַּיְיָ בְּסַעְדִי וְיִטְרִינַנִּי בְּאָרְחָא הָדֵין דִּי אֲנָא אָזֵל וְיִתֶּן לִי לַחֲמָא (נ''י לְחֵם) לְמֵיכַל וּכְסוּ לְמִלְבָּשׁ:
@12 וְאֵתוּב בִּשְׁלַם לְבֵית אַבָּא וִיהֵא מֵימְרָא דַיְיָ לִי לֵאלָהָא:
@13 וְאַבְנָא הָדָא דִי שַׁוֵּיתִי קָמָא תְּהֵי דִי אֵהֵי פָלַח עֲלַהּ קֳדָם יְיָ וְכֹל דִּי תִתֶּן לִי חַד מִן עַשְׂרָא אַפְרְשִׁנֵּהּ קֳדָמָךְ:
@14 וּנְטַל יַעֲקֹב רַגְלוֹהִי (נ''י רִיגְלוֹהִי) וַאֲזַל לַאֲרַע בְּנֵי מַדִינְחָא:
@15 וַחֲזָא וְהָא בֵירָא בְחַקְלָא וְהָא תַמָּן תְּלָתָא עֶדְרִין דְּעָן רְבֵעִין עֲלַהּ אֲרֵי מִן בֵּירָא הַהִיא מַשְׁקָן עֲדָרַיָּא וְאַבְנָא רַבְּתָא עַל פּוּמָא דְבֵירָא:
@16 וּמִתְכַּנְשִׁין לְתַמָּן כָּל עֲדָרַיָּא וּמְגַנְדְּרִין יָת אַבְנָא מֵעַל פּוּמָא דְבֵירָא וּמַשְׁקָן יָת עָנָא וּמְתִיבִין יָת אַבְנָא עַל פּוּמָא דְבֵירָא לְאַתְרַהּ:
@17 וַאֲמַר לְהוֹן יַעֲקֹב אַחַי מְנָן אַתּוּן וַאֲמָרוּ מֵחָרָן אֲנָחְנָא:
@18 וַאֲמַר לְהוֹן הַיְדַעְתּוּן יָת לָבָן בַּר נָחוֹר וַאֲמָרוּ יְדַעְנָן:
@19 וַאֲמַר לְהוֹן הַשְׁלַם לֵהּ וַאֲמָרוּ שְׁלַם וְהָא רָחֵל בְּרַתֵּהּ אַתְיָא עִם עָנָא:
@20 וַאֲמַר הָא עוֹד יוֹמָא סַגִי לָא עִדַן לְמִכְנַשׁ בְּעִיר אַשְׁקוּ עָנָא וְאִזִילוּ רְעוּ:
@21 וַאֲמָרוּ לָא נִכּוּל עַד דִי יִתְכַּנְשִׁין כָּל עֲדָרַיָּא וִיגַנְדְרוּן יָת אַבְנָא מֵעַל פוּמָא דְבֵירָא וְנַשְׁקֵי עָנָא:
@22 עַד דְהוּא מְמַלֵל עִמְהוֹן וְרָחֵל אָתַת עִם עָנָא דִי לַאֲבוּהָ אֲרֵי רָעִיתָא הִיא:
@23 וַהֲוָה כַּד חֲזָא יַעֲקֹב יָת רָחֵל בַּת לָבָן אֲחוּהָא דְאִמֵהּ וְיָת עָנָא דְלָבָן אֲחוּהָא דְאִמֵהּ וּקְרֵב יַעֲקֹב וּגַנְדַר יָת אַבְנָא מֵעַל פּוּמָא דְבֵירָא וְאַשְׁקֵי יָת עָנָא דְלָבָן אֲחוּהָא דְאִמֵהּ:
@24 וּנְשַׁק יַעֲקֹב לְרָחֵל וַאֲרֵם יָת קָלֵהּ וּבְכָא:
@25 וְחַוִּי יַעֲקֹב לְרָחֵל אֲרֵי בַר אֲחַת אָבוּהָא הוּא וַאֲרֵי בַר רִבְקָה הוּא וּרְהָטַת וְחַוִּיאַת לְאָבוּהָא:
@26 וַהֲוָה כַּד שְׁמַע לָבָן יָת שֵׁמַע יַעֲקֹב בַּר אֲחָתֵהּ וּרְהַט לְקַדָמוּתֵהּ וְגַפֵּף לֵהּ וְנַשִׁיק לֵהּ וְאַעֲלֵהּ לְבֵיתֵהּ וְאִשְׁתָּעִי לְלָבָן יָת כָּל פִּתְגָמַיָּא הָאִלֵּין:
@27 וַאֲמַר לֵהּ לָבָן בְּרַם קָרִיבִי וּבִשְׂרִי אָתְּ וִיתֵיב עִמֵּהּ יְרַח יוֹמִין:
@28 וַאֲמַר לָבָן לְיַעֲקֹב הֲמִדְּאָחִי אַתְּ וְתִפְלְחִנַּנִּי מַגָּן חַוִּי לִי מָה אַגְרָךְ:
@29 וּלְלָבָן תַּרְתֵּין בְּנָן שׁוּם רַבְּתָא לֵאָה וְשׁוּם זְעֶרְתָּא רָחֵל:
@30 וְעֵינֵי לֵאָה יָאֲיָן וְרָחֵל הֲוַת שַׁפִּירָא בְרֵיוָא וְיָאֲיָא בְחֶזְוָא:
@31 וּרְחֵם יַעֲקֹב יָת רָחֵל וַאֲמַר אֶפְלְחִנָּךְ שְׁבַע שְׁנִין בְּרָחֵל בְּרַתָּךְ זְעֶרְתָּא:
@32 וַאֲמַר לָבָן טַב דְּאֶתֵּן יָתַהּ לָךְ מִדְּאֶתֵּן יָתַהּ לִגְבַר אָחֳרָן תִּיב עִמִּי:
@33 וּפְלַח יַעֲקֹב בְּרָחֵל שְׁבַע שְׁנִין וַהֲווֹ בְעֵינוֹהִי כְּיוֹמִין זְעִירִין כַּד רְחֵים יָתַהּ:
@34 וַאֲמַר יַעֲקֹב לְלָבָן הַב יָת אִתְּתִי אֲרֵי אַשְׁלֵמִית יוֹמֵי פָלְחָנִי וְאֵעוֹל לְוָתַהּ:
@35 וּכְנַשׁ לָבָן יָת כָּל אֲנָשֵׁי אַתְרָא וַעֲבַד מִשְׁתְּיָא:
@36 וַהֲוָה בְרַמְשָׁא וּדְבַר יָת לֵאָה בְרַתֵּהּ וְאָעֵיל יָתַהּ לְוָתֵהּ וְעַל לְוָתַהּ:
@37 וִיהַב לָבָן לַהּ יָת זִלְפָּה אַמְתֵהּ לְלֵאָה בְרַתֵּהּ לְאַמְהוּ:
@38 וַהֲוָה בְצַפְרָא וְהָא הִיא לֵאָה וַאֲמַר לְלָבָן מָה דָּא עֲבַדְתָּ לִּי הֲלָא בְרָחֵל פְּלָחִית עִמָּךְ וּלְמָא שַׁקַּרְתָּ בִּי:
@39 וַאֲמַר לָבָן לָא יִתְעֲבֵד כְּדֵין בְּאַתְרָנָא לְמִתַּן זְעֶרְתָּא קֳדָם רַבְּתָא:
@40 אַשְׁלִים שְׁבוּעֲתָא דְדָא וְנִתֵּן לָךְ אַף יָת דָּא בְּפָלְחָנָא דִּי תִפְלַח עִמִּי עוֹד שְׁבַע שְׁנִין אָחֳרָנִין:
@41 וַעֲבַד יַעֲקֹב כֵּן וְאַשְׁלֵים שְׁבוּעֲתָא דְדָא וִיהַב לֵהּ יָת רָחֵל בְּרַתֵּהּ לֵהּ לְאִנְתּוּ:
@42 וִיהַב לָבָן לְרָחֵל בְּרַתֵּהּ יָת בִּלְהָה אַמְתֵהּ לַהּ לְאַמְהוּ:
@43 וְעַל אַף לְּוַת רָחֵל וּרְחֵים אַף יָת רָחֵל מִלֵּאָה וּפְלַח עִמֵּהּ עוֹד שְׁבַע שְׁנִין אָחֳרָנִין:
@44 וַחֲזָא יְיָ אֲרֵי שְׂנִיאֲתָא לֵאָה וִיהַב לַהּ עִדּוּי וְרָחֵל עַקְרָא:
@45 וְעַדִּיאַת לֵּאָה וִילִידַת בָּר וּקְרַת שְׁמֵהּ רְאוּבֵן אֲרֵי אֲמֶרֶת אֲרֵי גְלִי קֳדָם יְיָ עֻלְבּוֹנִי אֲרֵי כְעַן יְרַחֲמִנַנִי בַעֲלִי:
@46 וְעַדִּיאַת עוֹד וִילִידַת בָּר וַאֲמֶרֶת אֲרֵי שְׁמִיעַ קֳדָם יְיָ אֲרֵי שְׂנִיאֲתָא אֲנָא וִיהַב לִי אַף יָת דֵּין וּקְרַת שְׁמֵהּ שִׁמְעוֹן:
@47 וְעַדִּיאַת עוֹד וִילִידַת בָּר וַאֲמֶרֶת הָדָא זִמְנָא יִתְחַבַּר לִי בַעֲלִי אֲרֵי יְלֵידִית לֵהּ תְּלָתָא בְנִין עַל כֵּן קְרָא שְׁמֵהּ לֵוִי:
@48 וְעַדִּיאַת עוֹד וִילִידַת בָּר וַאֲמֶרֶת הָדָא זִמְנָא אוֹדֶה קֳדָם יְיָ עַל כֵּן קְרַת שְׁמֵהּ יְהוּדָה וְקָמַת מִלְּמֵילַד:
@49 וַחֲזַת רָחֵל אֲרֵי לָא יְלִידַת לְיַעֲקֹב וְקַנִּיאַת רָחֵל בַּאֲחָתַהּ וַאֲמֶרֶת לְיַעֲקֹב הַב לִי בְנִין וְאִם לָא מֵיתָא אֲנָא:
@50 וּתְקֵיף רוּגְזָא דְיַעֲקֹב בְּרָחֵל וַאֲמַר הָא מִנִּי אַתְּ בַּעְיָא הֲלָא מִן קֳדָם יְיָ תִּבְעִין דִּי מְנַע מִנִּיךְ וַלְדָא דִּמְעִין:
@51 וַאֲמֶרֶת הָא אַמְתִי בִלְהָה עוּל לְוָתַהּ וּתְלִיד וַאֲנָא אֱרַבֵּי וְאִתְבְּנֵי אַף אֲנָא מִנַּהּ:
@52 וִיהָבַת לֵהּ יָת בִּלְהָה אַמְתַהּ לְאִנְתּוּ וְעַל לְוָתַהּ יַעֲקֹב:
@53 וְעַדִּיאַת בִּלְהָה וִילִידַת לְיַעֲקֹב בַּר:
@54 וַאֲמֶרֶת רָחֵל דְּנַנִּי יְיָ וְאַף קַבִּיל צְלוֹתִי וִיהַב לִי בַּר עַל כֵּן קְרַת שְׁמֵהּ דָּן:
@55 וְעַדִּיאַת עוֹד וִילִידַת בִּלְהָה אַמְתָא דְרָחֵל בָּר תִּנְיָן לְיַעֲקֹב:
@56 וַאֲמֶרֶת רָחֵל קַבִּיל יְיָ בָּעוּתִי בְּאִתְחַנָּנוּתִי בִּצְלוֹתִי חֲמֵידַת דִּיהֵי לִי וְלַד כַּאֲחָתִי אַף אִתְיְהִיב לִי וּקְרַת שְׁמֵהּ נַפְתָּלִי:
@57 וַחֲזַת לֵּאָה אֲרֵי קָמַת מִלְּמֵילַד וּדְבָרַת יָת זִלְפָּה אַמְתַהּ וִיהָבַת יָתַהּ לְיַעֲקֹב לְאִנְתּוּ:
@58 וִילִידַת זִלְפָּה אַמְתָא דְלֵאָה לְיַעֲקֹב בָּר:
@59 וַאֲמֶרֶת לֵאָה אֲתָא גָד וּקְרַת יָת שְׁמֵהּ גָּד:
@60 וִילִידַת זִלְפָּה אַמְתָא דְלֵאָה בָּר תִּנְיָן לְיַעֲקֹב:
@61 וַאֲמֶרֶת לֵאָה תֻּשְׁבַּחְתָּא הֲוַת לִי אֲרֵי בְכֵן יְשַׁבְּחֻנַּנִּי נְשַׁיָּא וּקְרַת יָת שְׁמֵהּ אָשֵׁר:
@62 וַאֲזַל רְאוּבֵן בְּיוֹמֵי חֲצַד חִטִּין וְאַשְׁכַּח יַבְרוּחִין בְּחַקְלָא וְאַיְתִי יָתְהוֹן לְלֵאָה אִמֵּהּ וַאֲמֶרֶת רָחֵל לְלֵאָה הָבִי כְעַן לִי מִיַּבְרוּחֵי דִּבְרִיךְ:
@63 וַאֲמֶרֶת לַהּ הַזְעֵיר דִּדְבַרְתְּ יָת בַּעְלִי וְתִסְּבִין אַף יָת יַבְרוּחֵי דִּבְרִי וַאֲמֶרֶת רָחֵל בְּכֵן יִשְׁכּוּב עִמָּךְ בְּלֵילְיָא חֳלַף יַבְרוּחֵי דִּבְרִיךְ:
@64 וַאֲתָא (נ''י וְעַל) יַעֲקֹב מִן חַקְלָא בְּרַמְשָׁא וּנְפָקַת לֵאָה לְקַדָּמוּתֵהּ וַאֲמֶרֶת לְוָתִי תֵיעוֹל אֲרֵי מֵיגַר אֲגַרְתִּיךְ בְּיַבְרוּחֵי דִּבְרִי וּשְׁכִיב עִמַּהּ בְּלֵילְיָא הוּא:
@65 וְקַבִּיל יְיָ צְלוֹתַהּ דְּלֵאָה וְעַדִּיאַת וִילִידַת לְיַעֲקֹב בַּר חֲמִישָׁאֵי:
@66 וַאֲמֶרֶת לֵאָה יְהַב יְיָ אַגְרִי דִּי יְהָבִית אַמְתִי לְבַעְלִי וּקְרַת שְׁמֵהּ יִשָּׂשׂכָר:
@67 וְעַדִּיאַת עוֹד לֵאָה וִילִידַת בַּר שְׁתִיתָאֵי לְיַעֲקֹב:
@68 וַאֲמֶרֶת לֵאָה יְהַב יְיָ יָתֵהּ לִי חָלַק טַב הָדָא זִמְנָא יְהֵי מְדוֹרֵהּ דְּבַעְלִי לְוָתִי אֲרֵי יְלֵידִית לֵהּ שִׁתָּא בְנִין וּקְרַת יָת שְׁמֵהּ זְבֻלוּן:
@69 וּבָתַר כֵּן יְלִידַת בְּרַתָּא וּקְרַת יָת שְׁמַהּ דִּינָה:
@70 וְעַל דּוּכְרָנָא דְרָחֵל קֳדָם יְיָ וְקַבִּיל צְלוֹתַהּ יְיָ וִיהַב לַהּ עִדּוּי:
@71 וְעַדִּיאַת וִילִידַת בָּר וַאֲמֶרֶת כְּנַשׁ יְיָ יָת חִסּוּדִי:
@72 וּקְרַת יָת שְׁמֵהּ יוֹסֵף לְמֵימָר יוֹסֵף יְיָ לִי בַּר אָחֳרָן:
@73 וַהֲוָה כַּד יְלִידַת רָחֵל יָת יוֹסֵף וַאֲמַר יַעֲקֹב לְלָבָן שַׁלְּחַנִּי וְאֵיהַךְ לְאַתְרִי וּלְאַרְעִי:
@74 הַב יָת נְשַׁי וְיָת בְּנַי דִּי פְלָחִית יָתָךְ בְּהֵן וְאֵזִיל אֲרֵי אַתְּ יְדַעְתָּ יָת פָּלְחָנִי דִּי פְלָחִתָּךְ:
@75 וַאֲמַר לֵהּ לָבָן אִם כְּעַן אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ נַסֵּיתִי וּבָרְכַנִי יְיָ בְּדִילָךְ:
@76 וַאֲמָר פָּרֵישׁ אַגְרָךְ עֲלַי וְאֶתֵּן:
@77 וַאֲמַר לֵהּ אַתְּ יְדַעְתָּ יָת דִּי פְלָחִתָּךְ וְיָת דַּהֲוָה בְעִירָךְ עִמִּי:
@78 אֲרֵי זְעֵיר דִּי הֲוָה לָךְ קֳדָמַי וּתְקֵיף לְמִסְגֵּי וּבְרִיךְ יְיָ יָתָךְ בְּדִילִי וּכְעַן אֵימָתַי אֶעְבֵּיד אַף אֲנָא לְבֵיתִי:
@79 וַאֲמַר מָה אֶתֵּן לָךְ וַאֲמַר יַעֲקֹב לָא תִתֶּן לִי מִדַּעַם אִם תַּעְבֶּד לִי פִּתְגָּמָא הָדֵין אֱתוּב אֶרְעֵי עָנָךְ אֶטָּר:
@80 אֶעְבַּר בְּכָל עָנָךְ יוֹמָא דֵּין הַעֲדֵי (נ''י אַעְדִּי) מִתַּמָּן כָּל אִמָּר נְמוֹר וּרְקוֹעַ וְכָל אִמָּר שְׁחוּם בְּאִמְרַיָא וּרְקוֹעַ וּנְמוֹר בְּעִזַיָא וִיהֵי אַגְרִי:
@81 וְתַסְהֵד בִּי זָכוּתִי בְּיוֹם דִּמְחָר אֲרֵי תֵיעוֹל עַל אַגְרִי קֳדָמָךְ כֹּל דִּי לֵיתוֹהִי נְמוֹר וּרְקוֹעַ בְּעִזַּיָּא וּשְׁחוּם בְּאִמְרַיָא גְּנוּבָא הוּא עִמִּי:
@82 וַאֲמַר לָבָן בְּרַם לְוַי יְהֵי כְפִתְגָּמָךְ:
@83 וְאַעְדִּי בְיוֹמָא הַהוּא יָת תְּיָשַׁיָא רְגוֹלַיָא וּרְקוֹעַיָא וְיָת כָּל עִזַּיָא נְמוֹרְתָא וּרְקוֹעֲתָא כֹּל דִּי חִוָּר בֵּהּ וְכָל דִּשְׁחוּם בְּאִמְּרַיָּא וִיהַב בְּיַד בְּנוֹהִי:
@84 וְשַׁוִּי מַהֲלַךְ תְּלָתָא יוֹמִין בֵּינוֹהִי וּבֵין יַעֲקֹב וְיַעֲקֹב רָעֵי יָת עָנָא דְלָבָן דְּאִשְׁתָּאֳרָן:
@85 וּנְסִיב לֵהּ יַעֲקֹב חוּטְרִין דִּלְבָן רַטִּיבִין וִּדְלוּז וְדִדְלוּף וְקַלִּיף בְּהוֹן קִלְפִין חִוָּרִין קִלּוּף חִוָּר דִּי עַל חוּטְרַיָּא:
@86 וְדָעִיץ יָת חוּטְרַיָּא דִּי קַלִּיף בִּרְהָטַיָּא אֲתַר בֵּית שַׁקְיָא דְמַיָּא אֲתַר דְּאָתָן (נ''י דְּאָתְיָן) עָנָא לְמִשְׁתֵּי לְקִבְלֵיהוֹן דְּעָנָא וּמִתְיַחֲמָן בְּמֵיתֵיהוֹן לְמִשְׁתֵּי:
@87 וְאִתְיַחֲמָא עָנָא בְּחוּטְרַיָּא וִילִידָא עָנָא רְגוֹלִין נְמוֹרִין וּרְקוֹעִין:
@88 וְאִמְּרַיָּא אַפְרֵשׁ יַעֲקֹב וִיהַב בְּרֵישׁ עָנָא כָּל דִּרְגוֹל וְכָל דִּשְׁחוּם בְּעָנָא דְלָבָן וְשַׁוִּי לֵהּ עֶדְרִין בִּלְחוֹדוֹהִי וְלָא עֲרֵבִנּוּן עִם עָנָא דְלָבָן:
@89 וַהֲוֵי בְּכָל עִדַּן דְּמִתְיַחֲמָן עָנָא מְבַכַּרְתָּא וּמְשַׁוִּי יַעֲקֹב יָת חוּטְרַיָּא לְעֵינֵי עָנָא בִּרְהָטַיָּא לְיַחָמוּתְהוֹן בְּחוּטְרַיָּא:
@90 וּבְלַקִּישׁוּת עָנָא לָא מְשַׁוֵּי וַהֲווֹ לַקִּישָׁא לְלָבָן וּבַכִּירַיָּא לְיַעֲקֹב:
@91 וּתְקֵיף גַּבְרָא לַחֲדָא לַחֲדָא וַהֲווֹ לֵהּ עָן סַגִּיאָן וְאַמְהָן וְעַבְדִּין וְגַמְלִין וַחֲמָרִין:
@92 וּשְׁמַע יָת פִתְגָּמֵי בְנֵי לָבָן דְּאָמְרִין נְסִיב יַעֲקֹב יָת כָּל דִּי לְאָבוּנָא וּמִדִּי לְאָבוּנָא קְנָא יָת כָּל נִכְסַיָּא הָדֵין:
@93 וַחֲזָא יַעֲקֹב יָת סְבַר אַפֵּי לָבָן וְהָא לֵיתוֹהִי עִמֵּהּ כְּמֵאִתְמַלִּי וּמִדְּקַמּוֹהִי:
@94 וַאֲמַר יְיָ לְיַעֲקֹב תּוּב לְאַרְעָא דַּאֲבָהָתָךְ וּלְיַלָּדֻתָךְ וִיהֵי מֵימְרִי בְּסַעְדָּךְ:
@95 וּשְׁלַח יַעֲקֹב וּקְרָא לְרָחֵל וּלְלֵאָה לְחַקְלָא לְוַת עָנֵהּ:
@96 וַאֲמַר לְהֵן חָזֵי אֲנָא יָת סְבַר אַפֵּי אֲבוּכֶן אֲרֵי לֵיתוֹהִי עִמִּי כְּמֵאִתְמַלִּי וּמִדְּקַמֹּהִי וֵאלָהֵהּ דְּאַבָּא הֲוָה בְּסַעְדִּי:
@97 וְאַתִּין יְדַעְתִּין אֲרֵי בְּכָל חֵילִי פְּלָחִית יָת אֲבוּכֶן:
@98 וַאֲבוּכֶן שְׁקַּר בִּי וְאַשְׁנִי יָת אַגְרִי עֲשַׂר זִמְנִין וְלָא שָׁבְקֵהּ יְיָ לְאַבְאָשָׁא עִמִּי:
@99 אִם כְּדֵין הֲוָה אֲמַר נְמוֹרִין יְהֵא אַגְרָךְ וִילִידָן כָּל עָנָא נְמוֹרִין וְאִם כְּדֵין הֲוָה אֲמַר רְגוֹלִין יְהֵא אַגְרָךְ וִילִידָן כָּל עָנָא רְגוֹלִין:
@100 וְאַפְרֵשׁ יְיָ יָת גֵּיתֵי דַּאֲבוּכוֹן וִיהַב לִי:
@101 וַהֲוָה בְּעִדַּן דְּאִתְיַחֲמָא עָנָא וּזְקָפִית עַיְנַי וַחֲזֵית בְּחֶלְמָא וְהָא תְיָשַׁיָּא דְּסָלְקִין עַל עָנָא רְגוֹלִין נְמוֹרִין וּפַצִיחִין:
@102 וַאֲמַר לִי מַלְאָכָא דַּיְיָ בְּחֶלְמָא יַעֲקֹב וַאֲמָרִית הָא אֲנָא:
@103 וַאֲמַר זְקוֹף כְּעַן עַינָיךְ וַחֲזֵי כָּל תְּיָשַׁיָּא דְּסָלְקִין עַל עָנָא רְגוֹלִין נְמוֹרִין וּפַצִיחִין אֲרֵי גְלֵי קֳדָמַי יָת כָּל דִּי לָבָן עָבֵד לָךְ:
@104 אֲנָא אֱלָהָא דְּאִתְגְּלֵיתִי עֲלָךְ בְּבֵית אֵל דִּי מְשַׁחְתָּא תַמָּן קָמָא דִּי קַיִּמְתָּא קֳדָמַי תַּמָּן קְיָם כְּעַן קוּם פּוּק מִן אַרְעָא הָדָא וְתוּב לְאַרְעָא יַלָּדוּתָךְ:
@105 וַאֲתִיבַת רָחֵל וְלֵאָה וַאֲמָרַן לֵהּ הַעוֹד (כְּעַן) לָנָא חֳלָק וְאַחֲסָנָא בְּבֵית אֲבוּנָא:
@106 הֲלָא נוּכְרָאָן אִתְחֲשַׁבְנָא לֵהּ אֲרֵי זַבְּנָנָא וַאֲכַל אַף מֵיכַל יָת כַּסְפָּנָא:
@107 אֲרֵי כָל עוּתְרָא דִּי אַפְרֵשׁ יְיָ מֵאֲבוּנָא דִּילָנָא הוּא וְדִבְּנָנָא וּכְעַן כֹּל דִּי אֲמַר יְיָ לָךְ עִבֵד:
@108 וְקָם יַעֲקֹב וּנְטַל יָת בְּנוֹהִי וְיָת נְשׁוֹהִי עַל גַּמְלַיָּא:
@109 וּדְבַר יָת כָּל גֵּיתוֹהִי וְיָת כָּל קִנְיָנֵהּ דִּקְנָא גֵּיתֵי קִנְיָנֵהּ דִּי קְנָא בְּפַדַּן אֲרָם לְמֵיתֵי לְוַת יִצְחָק אֲבוּהִי לְאַרְעָא כְנָעַן:
@110 וְלָבָן אֲזַל לְמִגַּז יָת עָנֵהּ וּנְסִּבַת רָחֵל יָת צַלְמָנַיָּא דִּי לַאֲבוּהָא:
@111 וְכַסִּי יַעֲקֹב מִן לִבָּא דְלָבָן אֲרַמָּאָה עַל דְּלָא חַוִּי לֵהּ אֲרֵי אָזֵל הוּא:
@112 וַאֲזַלּ הוּא וְכָל דִּי לֵהּ וְקָם וַעֲבַר יָת פְּרָת וְשַׁוִּי יָת אַפּוֹהִי לְטוּרָא דְגִלְעָד:
@113 וְאִתְחַוָא לְלָבָן בְּיוֹמָא תְלִיתָאָה אֲרֵי אֲזַל יַעֲקֹב:
@114 וּדְבַר יָת אַחוּהִי עִמֵּהּ וּרְדַף בַּתְרוֹהִי מַהֲלַךְ שִׁבְעַת יוֹמִין וְאַדְבֵּק יָתֵהּ בְּטוּרָא דְגִלְעָד:
@115 וַאֲתָא מֵימָר מִן קֳדָם יְיָ לְוַת לָבָן אֲרַמָּאָה בְּחֵילְמָא דְּלֵילְיָא וַאֲמַר לֵהּ אִסְתַּמַּר לָךְ דִּילְמָא תְמַלֵּיל עִם יַעֲקֹב מִטַּב עַד בִּישׁ:
@116 וְאַדְבֵּיק לָבָן יָת יַעֲקֹב וְיַעֲקֹב פְּרַס יָת מַשְׁכְּנֵהּ בְּטוּרָא וְלָבָן אַשְׁרֵי יָת אֲחוֹהִי בְּטוּרָא דְגִלְעָד:
@117 וַאֲמַר לָבָן לְיַעֲקֹב מָה עֲבַדְתָּ וְכַסֵּיתָא מִנִּי וּדְבַרְתָּא יָת בְּנָתַי כְּשַׁבְיוֹת חַרְבָּא:
@118 לְמָה אִטְמַרְתָּ לְמֵיזַל וְכַסֵּיתָא מִנִּי וְלָא חַוֵּיתָא לִי וְשַׁלָּחִתָּךְ פּוֹן בְּחֶדְוָא וּבְתוּשְׁבְּחָן בְּתוּפִּין וּבְכִנָּרִין:
@119 וְלָא שְׁבַקְתַּנִּי לְנַשָּׁקָא לִבְנַי וְלִבְנָתָי כְּעַן אַסְכֶּלְתָּא לְמֶעְבָּד:
@120 אִית חֵילָא בִידִי לְמֶעְבַּד עִמְּכוֹן בִּישׁ וֵאלָהָא דַּאֲבוּכוֹן בְּרַמְשָׁא אֲמַר לִי לְמֵימַר אִסְתַּמַּר לָּךְ מִלְּמַלָּלָא עִם יַעֲקֹב מִטַּב עַד בִּישׁ:
@121 וּכְעַן מֵיזַל אֲזַלְתָּ אֲרֵי חַמָּדָא חַמֵדְתָּא לְבֵית אָבוּךְ לְמָה נְסִבְתָּא יָת דַּחַלְתִּי:
@122 וַאֲתֵיב יַעֲקֹב וַאֲמַר לְלָבָן אֲרֵי דְחֵילִית אֲרֵי אֲמָרִית דִּילְמָא תָנֵיס יָת בְּנָתָךְ מִנִּי:
@123 עִם (נ''י אֲתַר) דִּי תַשְׁכַּח יָת דַּחַלְתָּךְ לָא יִתְקַיַּם קֳדָם אֲחָנָא אִשְׁתְּמוֹדַע לָךְ מָה דְעִמִּי וְסַב לָךְ וְלָא יְדַע יַעֲקֹב אֲרֵי רָחֵל נְסִיבָתְהוֹן:
@124 וְעַל לָבָן בְּמַשְׁכְּנָא דְיַעֲקֹב וּבְמַשְׁכְּנָא דְלֵאָה וּבְמַשְׁכְּנָא דְּתַרְתֵּין לְחֵינָתָא וְלָא אַשְׁכַּח וּנְפַק מִמַּשְׁכְּנָא דְלֵאָה וְעַל בְּמַשְׁכְּנָא דְרָחֵל:
@125 וְרָחֵל נְסִיבַת יָת צַלְמָנַיָּא וְשַׁוִּתִּנּוּן בַּעֲבִיטָא דְגַמְלָא וִיתִיבַת עֲלֵיהוֹן וּמַשִּׁישׁ לָבָן יָת כָּל מַשְׁכְּנָא וְלָא אַשְׁכָּח:
@126 וַאֲמֶרֶת לַאֲבוּהָא לָא יִתְקֵף בְּעֵינֵי רִבּוֹנִי אֲרֵי לָא אִכּוּל לְמֵיקַם מִן קֳדָמָךְ אֲרֵי אֹרַח נְשִׁין לִי וּבְלַשׁ וְלָא אַשְׁכַּח יָת צַלְמָנַיָּא:
@127 וּתְקֵיף לְיַעֲקֹב וּנְצָא עִם לָבָן וַאֲתֵיב יַעֲקֹב וַאֲמַר לְלָבָן מַה חוֹבִי מַה סוּרְחָנִי אֲרֵי רְדַפְתָּא בַּתְרָי:
@128 אֲרֵי מַשִּׁשְׁתָּא יָת כָּל מָנַי מָה אַשְׁכַּחְתָּא מִכֹּל מָנֵי בֵיתָךְ שַׁוִּי הָכָא קֳדָם אַחַי וְאַחָיךְ וְיוֹכִיחוּן בֵּין תַּרְוָנָא:
@129 דְּנַן עֶסְרִין שְׁנִין אֲנָא עִמָּךְ רְחֵלָיךְ וְעִזָּיךְ לָא אַתְכִּילוּ וְדִכְרֵי עָנָךְ לָא אֲכָלִית:
@130 דִּתְבִירָא לָא אַיְתֵיתִי לְוָתָךְ דַּהֲוַת שָׁגְיָא מִמִּנְיָנָא מִנִּי אַתְּ בָּעֵי לַהּ נְטָרִית בִּימָמָא וּנְטָּרִית בְּלֵילְיָא:
@131 הֲוֵיתִי בִימָמָא אֲכַלְנִי שַׁרְבָא וּגְלִידָא (הֲוָה) נָחֵית עֲלַי בְּלֵילְיָא וּנְדַד שִׁנְתִּי מֵעֵינָי:
@132 דְּנַן לִי עֶשְׂרִין שְׁנִין בְּבֵיתָךְ פְּלָחִתָּךְ אַרְבַּע עֶשְׂרֵי שְׁנִין בְּתַרְתֵּין בְּנָתָךְ וְשִׁתְּ שְׁנִין בְּעָנָךְ וְאַשְׁנֵיתָא יָת אַגְרִי עֲשַׂר זִמְנִין:
@133 אִילוּלָא פוֹן אֱלָהֵהּ דְּאַבָּא אֱלָהֵהּ דְּאַבְרָהָם וּדְדָחִיל לֵהּ יִצְחָק הֲוָה בְּסַעְדִּי אֲרֵי כְעַן רֵיקָן שִׁלַּחְתָּנִי יָת עַמְלִי וְיָת לֵיאוּת יְדַי גְלֵי קֳדָם יְיָ וְאוֹכַח בְּרַמְשָׁא:
@134 וַאֲתֵיב לָבָן וַאֲמַר לְיַעֲקֹב בְּנָתָא בְּנָתַי וּבְנַיָּא בְנַי וְעָנָא עָנִי וְכֹל דִּי אַתְּ חָזֵי דִּילִי הוּא וְלִבְנָתַי מָה אֶעְבֵּיד לְאִלֵּין יוֹמָא דֵין אוֹ לִבְנֵיהֶן דִּילִידָן:
@135 וּכְעַן אֱתָא נִגְזַר קְיָם אֲנָא וְאָתְּ וִיהֵי לְסָהִיד בֵּינִי וּבֵינָךְ:
@136 וּנְסִיב יַעֲקֹב אַבְנָא וּזְקָפַהּ קָמָא:
@137 וַאֲמַר יַעֲקֹב לַאֲחוֹהִי לְקוּטוּ אַבְנִין וּנְסִיבוּ אַבְנִין וַעֲבָדוּ דְּגוֹרָא וַאֲכָלוּ תַמָּן עַל דְּגוֹרָא:
@138 וּקְרָא לֵהּ לָבָן יְגַר שָׂהֲדוּתָא וְיַעֲקֹב קְרָא לֵהּ גַּלְעֵד:
@139 וַאֲמַר לָבָן דְּגוֹרָא הָדֵין סָהִיד בֵּינִי וּבֵינָךְ יוֹמָא דֵּין עַל כֵּן קְרָא שְׁמֵהּ גַּלְעֵד:
@140 וְסָכוּתָא דִּי אֲמַר יִסֶּךְ מֵימְרָא דַּיְיָ בֵּינִי וּבֵינָךְ אֲרֵי נִתכַּסִּי גּבַר מֵחַבְרֵהּ:
@141 אִם תְּעַנֵּי יָת בְּנָתַי וְאִם תִּסַּב נְשִׁין עַל בְּנָתַי לֵית אֱנַשׁ עִמָּנָא חָזֵי מֵימְרָא דַּיְיָ סָהִיד בֵּינִי וּבֵינָךְ:
@142 וַאֲמַר לָבָן לְיַעֲקֹב הָא דְּגוֹרָא הָדֵין וְהָא קַמְתָא דִּי אֲקֵימִית בֵּינִי וּבֵינָךְ:
@143 סָהִיד דְּגוֹרָא הָדֵין וְסָהֲדָא קָמָא אִם אֲנָא לָא אֶעְבַּר לְוָתָךְ יָת דְּגוֹרָא הָדֵין וְאִם אַתְּ לָא תֵעִבַּר לְוָתִי יָת דְּגוֹרָא הָדֵין וְיָת קַמְתָא הָדָא לְבִישׁוּ:
@144 אֱלָהֵהּ דְּאַבְרָהָם וֵאֱלָהֵהּ דְּנָחוֹר יְדוּנוּן בֵּינָנָא אֱלָהֵהּ דַּאֲבוּהוֹן וְקַיֵּים יַעֲקֹב בִּדְדָחִיל לֵהּ אֲבוּהִי יִצְחָק:
@145 וּנְכֵס יַעֲקֹב נִכְסָתָא בְּטּוּרָא וּקְרָא לַאֲחוֹהִי לְמֵיכַל לַחְמָא וַאֲכָלוּ לַחְמָא וּבִיתוּ בְּטוּרָא:
@146 וְאַקְדֵּם לָבָן בְּצַפְרָא וּנְשַׁק לִבְנוֹהִי וְלִבְנָתֵהּ וּבָרִיךְ יָתְהֵן וַאֲזַל וְתַב לָבָן לְאַתְרֵהּ:
@147 וְיַעֲקֹב אֲזָל לְאָרְחֵהּ וַעֲרָעוּ בֵהּ מַלְאָכַיָּא דַּיְיָ:
@148 וַאֲמַר יַעֲקֹב כַּד חֲזָנוּן מַשְׁרִיתָא מִן קֳדָם יְיָ דֵּין וּקְרָא שְׁמָא דְאַתְרָא הַהוּא מַחֲנָיִם: פפפ:

@1 **ויצא יעקב.** על ידי שבשביל שרעות בנות כנען בעיני יצחק אביו הלך עשו אל ישמעאל, הפסיק הענין בפרשתו של יעקב וכתב (לעיל כח ו) וירא עשו כי ברך וגו' , ומשגמר חזר לענין הראשון: **ויצא יעקב מבאר שבע.** לא היה צריך לכתוב אלא וילך יעקב חרנה, ולמה הזכיר יציאתו, אלא מגיד שיציאת צדיק מן המקום עושה רושם, שבזמן שהצדיק בעיר הוא הודה הוא זיוה הוא הדרה, יצא משם פנה הודה פנה זיוה פנה הדרה וכן (רות א ז) ותצא מן המקום, האמור בנעמי ורות: **וילך חרנה.** יצא ללכת לחרן:
@2 **ויפגע במקום.** לא הזכיר הכתוב באיזה מקום אלא במקום הנזכר במקום אחר, הוא הר המוריה שנאמר בו (לעיל כב ד) וירא את המקום מרחוק: **ויפגע.** כמו (יהושע טז ז) ופגע ביריחו, (שם יט יא) ופגע בדבשת. ורבותינו פרשו לשון תפלה כמו (ירמיה ז טז) ואל תפגע בי, ולמדנו שתקן תפלת ערבית. ושנה הכתוב ולא כתב ויתפלל, ללמדך שקפצה לו הארץ, כמו שמפורש בפרק גיד הנשה (חלין צא ב) : **כי בא השמש.** היה לו לכתוב ויבא השמש. כי בא השמש, משמע ששקעה לו חמה פתאם שלא בעונתה כדי שילין שם: **וישם מראשותיו.** עשאן כמין מרזב סביב לראשו שהיה ירא מפני חיות רעות. התחילו מריבות זו עם זו, זאת אומרת עלי יניח צדיק את ראשו, וזאת אומרת עלי יניח, מיד עשאן הקדוש ברוך הוא אבן אחת, וזהו שנאמר (פסוק יח) ויקח את האבן אשר שם מראשותיו: **וישכב במקום ההוא.** לשון מעוט באותו מקום שכב, אבל ארבע עשרה שנים ששמש בבית עבר לא שכב בלילה, שהיה עוסק בתורה:
@3 **עולים ויורדים.** עולים תחלה ואחר כך יורדים, מלאכים שלווהו בארץ אין יוצאים חוצה לארץ ועלו לרקיע, וירדו מלאכי חוצה לארץ ללוותו:
@4 **נצב עליו.** לשמרו: **ואלהי יצחק.** אף על פי שלא מצינו במקרא שיחד הקדוש ברוך הוא שמו על הצדיקים בחייהם לכתוב אלהי פלוני, משום שנאמר (איוב טו טו) הן בקדושיו לא יאמין, כאן ייחד שמו על יצחק לפי שכהו עיניו וכלוא היה בבית, והרי הוא כמת, ויצר הרע פסק ממנו: **שכב עליה.** קפל הקדוש ברוך הוא כל ארץ ישראל תחתיו, רמז לו שתהא נחה לכבש לבניו:
@5 **ופרצת.** וחזקת, כמו (שמות א יב) וכן יפרוץ:
@6 **אנכי עמך.** לפי שהיה ירא מעשו ומלבן: **עד אשר אם עשיתי.** אם משמש בלשון כי: **דברתי לך.** לצרכך ועליך, מה שהבטחתי לאברהם על זרעו, לך הבטחתיו ולא לעשו, שלא אמרתי לו כי יצחק יקרא לך זרע, אלא כי ביצחק, ולא כל. יצחק וכן כל לי ולך ולו ולהם הסמוכים אצל דבור, משמשים לשון על, וזה, יוכיח שהרי עם יעקב לא דבר קדם לכן:
@7 **ואנכי לא ידעתי.** שאלו ידעתי לא ישנתי במקום קדוש כזה:
@8 **כי אם בית אלהים.** אמר רבי אלעזר בשם רבי יוסי בן זמרא הסלם הזה עומד בבאר שבע ואמצע שפועו מגיע כנגד בית המקדש, שבאר שבע עומד בדרומה של יהודה, וירושלים בצפונה בגבול שבין יהודה ובנימין, ובית אל היה בצפון של נחלת בנימין בגבול שבין בנימין ובין בני יוסף, נמצא סלם שרגליו בבאר שבע וראשו בבית אל מגיע אמצע שפועו נגד ירושלים. וכלפי שאמרו רבותינו שאמר הקדוש ברוך הוא צדיק זה בא לבית מלוני ויפטר בלא לינה, ועוד אמרו יעקב קראה לירושלים בית אל וזו לוז היא ולא ירושלים ומהיכן למדו לומר כן. אומר אני שנעקר הר המוריה ובא לכאן, וזהו היא קפיצת הארץ האמורה בשחיטת חלין (חולין צא ב) , שבא בית המקדש לקראתו עד בית אל, וזהו ויפגע במקום. [ואם תאמר וכשעבר יעקב על בית המקדש מדוע לא עכבו שם, איהו לא יהב לביה להתפלל במקום שהתפללו אבותיו, ומן השמים יעכבוהו, איהו עד חרן אזל כדאמרינן בפרק גיד הנשה (חולין צא ב) , וקרא מוכיח וילך חרנה, כי מטא לחרן אמר אפשר שעברתי על מקום שהתפללו אבותי ולא התפללתי בו, יהב דעתיה למהדר וחזר עד בית אל וקפצה לו הארץ]: **מה נורא.** תרגום מה דחילו אתרא הדין. דחילו שם דבר הוא, כמו סוכלתנו, וכסו למלבש: **וזה שער השמים.** מקום תפלה לעלות תפלתם השמימה. ומדרשו שבית המקדש של מעלה מכון כנגד בית המקדש של מטה כ **אם יהיה אלהים עמדי.** אם ישמור לי הבטחות הללו שהבטיחני להיות עמדי, כמו שאמר לי (פסוק טו) והנה אנכי עמך: **ושמרני.** כמו שאמר לי (פסוק טו) ושמרתיך בכל אשר תלך: **ונתן לי לחם לאכול.** כמו שאמר (פסוק טו) כי לא אעזבך, והמבקש לחם הוא קרוי נעזב, שנאמר (תהלים לז כה) ולא ראיתי צדיק נעזב וזרעו מבקש לחם:
@12 **ושבתי.** כמו שאמר לי (פסוק טו) והשיבותיך אל האדמה: **בשלום.** שלם מן החטא, שלא אלמד מדרכי לבן: **והיה ה' לי לאלהים.** שיחול שמו עלי מתחלה ועד סוף, שלא ימצא פסול בזרעי, כמו שנאמר (פסוק טו) אשר דברתי לך, והבטחה זו הבטיח לאברהם, שנאמר (שם יז ז) להיות לך לאלהים ולזרעך אחריך:
@13 **והאבן הזאת.** כך תפרש וי''ו זו של והאבן, אם תעשה לי את אלה, אף אני אעשה זאת: **והאבן הזאת אשר שמתי מצבה** וגו' **.** כתרגומו אהי פלח עלה קדם ה' וכן עשה בשובו מפדן ארם, כשאמר לו (לקמן לה א) קום עלה בית אל, מה נאמר שם (שם יד) ויצב יעקב מצבה וגו' ויסך עליה נסך:
@14 **וישא יעקב רגליו.** משנתבשר בשורה טובה שהובטח בשמירה, נשא לבו את רגליו ונעשה קל ללכת. כך מפרש בבראשית רבה (ע ח) :
@15 **ישקו העדרים.** משקים הרועים את העדרים, והמקרא דבר בלשון קצרה:
@16 **ונאספו.** רגילים היו להאסף לפי שהיתה האבן גדולה: **וגללו.** וגוללין ותרגומו ומגנדרין, כל לשון הוה משתנה לדבר בלשון עתיד ובלשון עבר לפי שכל דבר ההוה תמיד כבר היה ועתיד להיות: **והשיבו.** תרגומו ומתיבין:
@19 **באה עם הצאן.** הטעם באל''ף, ותרגומו אתיא. (פסוק ט) ורחל באה, הטעם למעלה בבי''ת ותרגומו אתת. הראשון לשון עושה, והשני לשון עשתה:
@20 **הן עוד היום גדול.** לפי שראה אותם רובצים, כסבור שרוצים לאסוף המקנה הביתה ולא ירעו עוד, אמר להם הן עוד היום גדול, כלומר אם שכירים אתם לא שלמתם פעלת היום, ואם הבהמות שלכם אף על פי כן לא עת האסף המקנה וגו' :
@21 **לא נוכל.** להשקות, לפי שהאבן גדולה: **וגללו.** זה מתורגם ויגנדרון, לפי שהוא לשון עתיד:
@23 **ויגש יעקב ויגל.** כזה שמעביר את הפקק מעל פי צלוחית, להודיעך שכחו גדול:
@24 **ויבך.** לפי שצפה ברוח הקודש שאינה נכנסת עמו לקבורה. דבר אחר לפי שבא בידים ריקניות, אמר אליעזר עבד אבי אבא היו בידיו נזמים וצמידים ומגדנות, ואני אין בידי כלום. לפי שרדף אליפז בן עשו במצות אביו אחריו להרגו והשיגו, ולפי שגדל אליפז בחיקו של יצחק משך ידו. אמר לו מה אעשה לצווי של אבא, אמר לו יעקב טול מה שבידי, והעני חשוב כמת:
@25 **כי אחי אביה הוא.** קרוב לאביה, כמו (לעיל יג ח) אנשים אחים אנחנו. ומדרשו אם לרמאות הוא בא גם אני אחיו ברמאות, ואם אדם כשר הוא, גם אני בן רבקה אחותו הכשרה: **ותגד לאביה.** לפי שאמה מתה לא היה לה להגיד אלא לו:
@26 **וירץ לקראתו.** כסבור ממון הוא טעון, שהרי עבד הבית בא לכאן בעשרה גמלים טעונים: **ויחבק.** כשלא ראה עמו כלום אמר שמא זהובים הביא והנם בחיקו: **וינשק לו.** אמר שמא מרגליות הביא והם בפיו: **ויספר ללבן.** שלא בא אלא מתוך אונס אחיו, ושנטלו ממונו ממנו:
@27 **אך עצמי ובשרי.** מעתה אין לי לאספך הביתה הואיל ואין בידך כלום, אלא מפני קורבה אטפל בך חדש ימים, וכן עשה ואף זו לא לחנם שהיה רועה צאנו:
@28 **הכי אחי אתה.** לשון תמה, וכי בשביל שאחי אתה תעבדני חנם: **ועבדתני.** כמו ותעבדני, וכן כל תבה שהיא לשון עבר הוסיף וי''ו בראשה היא הופכת התבה להבא:
@30 **ועיני לאה רכות.** שהיתה סבורה לעלות בגורלו של עשו ובוכה שהיו הכל אומרים שני בנים לרבקה ושתי בנות ללבן, הגדולה לגדול והקטנה לקטן: **תאר.** הוא צורת הפרצוף לשון (ישעיה מד יג) יתארהו בשרד, קונפ''ס בלע''ז : **מראה.** הוא זיו קלסתר:
@31 **אעבדך שבע שנים.** הם ימים אחדים שאמרה לו אמו (לעיל כז מד) וישבת עמו ימים אחדים. ותדע שכן הוא, שהרי כתיב (להלן פסוק כ) ויהיו בעיניו כימים אחדים: **ברחל בתך הקטנה.** כל הסימנים הללו למה, לפי שיודע בו שהוא רמאי אמר לו אעבדך ברחל, ושמא תאמר רחל אחרת מן השוק, תלמוד לומר בתך, ושמא תאמר אחליף ללאה שמה ואקרא שמה רחל, תלמוד לומר הקטנה ואף על פי כן לא הועיל לו שהרי רמהו:
@34 **מלאו ימי.** שאמרה לי אמי. ועוד מלאו ימי, שהרי אני בן שמונים וארבע שנה ואימתי אעמיד שנים עשר שבטים, וזהו שאמר ואבואה אליה, והלא קל שבקלים אינו אומר כן, אלא להוליד תולדות אמר כן:
@38 **ויהי בבקר והנה היא לאה.** אבל בלילה לא היתה לאה, לפי שמסר יעקב לרחל סימנים, וכשראתה רחל שמכניסין לו לאה אמרה עכשיו תכלם אחותי, עמדה ומסרה לה אותן סימנים:
@40 **מלא שבוע זאת.** דבוק הוא שהרי נקוד בחטף שבוע של זאת, והן שבעת ימי המשתה בתלמוד ירושלמי במועד קטן (א ז) . ואי אפשר לומר שבוע ממש, שאם כן היה צריך לנקד בפתח השין. ועוד ששבוע לשון זכר, כדכתיב (דברים טז ט) שבעה שבעת תספר לך, לפיכך אין משמע שבוע אלא שבעה שייטיינ''א בלע''ז : **ונתנה לך.** לשון רבים, כמו (לעיל יא ז) נרדה ונבלה, (שם ג) ונשרפה, אף זה לשון ונתן **גם את זאת.** [מיד לאחר שבעת ימי המשתה] ותעבוד לאחר נשואיה:
@43 **ויעבוד עמו עוד שבע שנים אחרות.** הקישן לראשונות, מה ראשונות באמונה אף האחרונות באמונה, ואף על פי שברמאות בא עליו:
@45 **ותקרא שמו ראובן.** רבותינו פרשו, אמרה ראו מה בין בני לבן חמי שמכר הבכורה ליעקב, וזה לא מכרה ליוסף ולא ערער עליו, ולא עוד שלא ערער עליו אלא שבקש להוציאו מן הבור:
@47 **הפעם ילוה אישי.** לפי שהאמהות נביאות היו ויודעות ששנים עשר שבטים יוצאים מיעקב וארבע נשים ישא, אמרה מעתה אין לו פתחון פה עלי, שהרי נטלתי כל חלקי בבנים: **על כן.** כל מי שנאמר בו על כן מרבה באוכלוסין, חוץ מלוי שהארון היה מכלה בהם: **קרא שמו לוי.** תמהתי שבכלם כתיב ותקרא, וזה כתב בו קרא, ויש מדרש אגדה באלה הדברים רבה ששלח הקדוש ברוך הוא גבריאל והביאו לפניו וקרא לו שם זה ונתן לו עשרים וארבע מתנות כהנה, ועל שם שלוהו במתנות קראו לוי:
@48 **הפעם אודה.** שנטלתי יותר מחלקי, מעתה יש לי להודות:
@49 **ותקנא רחל באחותה.** קנאה במעשיה הטובים, אמרה אלולי שצדקה ממני לא זכתה לבנים: **הבה לי.** וכי כך עשה אביך לאמך, והלא התפלל עליה: **מתה אנכי.** מכאן למי שאין לו בנים שחשוב כמת:
@50 **התחת אלהים אנכי.** וכי במקומו אני: **אשר מנע ממך.** את אמרת שאעשה כאבא, אני איני כאבא, אבא לא היו לו בנים אני יש לי בנים, ממך מנע ולא ממני:
@51 **על ברכי.** כתרגומו ואנא ארבי: **ואבנה גם אנכי.** מהו גם, אמרה לו זקנך אברהם היו לו בנים מהגר, וחגר מתניו כנגד שרה, אמר לה זקנתי הכניסה צרתה לביתה, אמרה לו אם הדבר הזה מעכב, הנה אמתי בלהה, ואבנה גם אנכי ממנה כשרה:
@54 **דנני אלהים.** דנני וחיבני וזכני:
@56 **נפתולי אלהים.** מנחם בן סרוק פרשו במחברת (במדבר יט טו) צמיד פתיל, חבורים, מאת המקום נתחברתי עם אחותי לזכות לבנים. ואני מפרשו לשון (דברים לב ה) עקש ופתלתול, נתעקשתי והפצרתי פצירות ונפתולים הרבה למקום להיות שוה לאחותי: **גם יכלתי.** הסכים על ידי. ואונקלוס תרגם לשון תפלה, כמו נפתולי אלהים, נתפללתי בקשות החביבות לפניו, נתקבלתי ונעתרתי כאחותי: **נפתלתי.** נתקבלה תפלתי. ומדרש אגדה יש רבים בלשון נוטריקון:
@58 **ותלד זלפה.** בכלן נאמר הריון חוץ מזלפה לפי שהיתה בחורה מכולן ותינוקת בשנים ואין הריון נכר בה, וכדי לרמות ליעקב נתנה לבן ללאה שלא יבין שמכניסין לו את לאה, שכך מנהג לתן שפחה גדולה לגדולה וקטנה לקטנה:
@59 **בא גד.** בא מזל טוב, כמו (שבת סז ב) גד גדי וסנוק לא, ודומה לו (ישעיה סה יא) העורכים לגד שלחן. ומדרש אגדה שנלד מהול, כמו (דניאל ד כ) גדו אילנא, ולא ידעתי על מה נכתבה תבה אחת. דבר אחר למה נקראת תיבה אחת בגד, כמו בגדת בי כשבאת אל שפחתי, כאיש שבגד באשת נעורים:
@62 **בימי קציר חטים.** להגיד שבחן של שבטים, שעת הקציר היה ולא פשט ידו בגזל להביא חטים ושעורים אלא דבר ההפקר שאין אדם מקפיד בו: **דודאים.** סיגלי, עשב הוא ובלשון ישמעאל יסמי''ן:
@63 **ולקחת גם את דודאי בני.** בתמיהה, ולעשות עוד זאת לקח גם את דודאי בני ותרגומו ולמסב: **לכן ישכב עמך הלילה.** שלי היתה שכיבת לילה זו ואני נותנה לך תחת דודאי בנך. ולפי שזלזלה במשכב הצדיק לא זכתה להקבר עמו:
@64 **שכר שכרתיך.** נתתי לרחל שכרה: **בלילה הוא.** הקדוש ברוך הוא סיע שיצא משם יששכר:
@65 **וישמע אלהים אל לאה.** שהיתה מתאוה ומחזרת להרבות שבטים:
@68 **זבד טוב.** כתרגומו: **יזבלני.** לשון (מלכים א' ח יג) בית זבול הירבירייריא''ה בלע''ז בית מדור. מעתה לא תהא עיקר דירתו אלא עמי שיש לי בנים כנגד כל נשיו:
@69 **דינה.** פרשו רבותינו שדנה לאה דין בעצמה אם זה זכר לא תהא רחל אחותי כאחת השפחות, והתפללה עליו ונהפך לנקבה:
@70 **ויזכר אלהים את רחל.** זכר לה שמסרה סימניה לאחותה, ושהיתה מצרה שלא תעלה בגורלו של עשו שמא יגרשנה יעקב לפי שאין לה בנים, ואף עשו הרשע כך עלה בלבו כששמע שאין לה בנים. הוא שיסד הפיט (קרובות דר''ה שחרית) האדמון כבט שלא חלה, צבה לקחתה לו ונתבהלה:
@71 **אסף.** הכניסה במקום שלא תראה וכן (ישעיה ד א) אסף חרפתנו, (שמות ט יט) ולא יאסף הביתה, (יואל ד טו) אספו נגהם, (ישעיה ס כ) וירחך לא יאסף, לא יטמן: **חרפתי.** שהייתי לחרפה שאני עקרה, והיו אומרים עלי שאעלה לחלקו של עשו הרשע. ומדרש אגדה כל זמן שאין לאשה בן אין לה במי לתלות סרחונה, משיש לה בן תולה בו. מי שבר כלי זה, בנך, מי אכל תאנים אלו, בנך:
@72 **יוסף ה' לי בן אחר.** יודעת היתה בנבואה שאין יעקב עתיד להעמיד אלא שנים עשר שבטים, אמרה יהי רצון שאותו שהוא עתיד להעמיד יהא ממני, לכך לא נתפללה אלא על בן אחר:
@73 **כאשר ילדה רחל את יוסף.** משנלד שטנו של עשו, שנאמר (עובדיה א יח) והיה בית יעקב אש ובית יוסף להבה ובית עשו לקש, אש בלא להבה אינו שולט למרחוק, משנלד יוסף בטח יעקב בהקדוש ברוך הוא ורצה לשוב:
@74 **תנה את נשי** וגו' **.** איני רוצה לצאת כי אם ברשות:
@75 **נחשתי.** מנחש היה, נסיתי בנחוש שלי שעל ידך באה לי ברכה, כשבאת לכאן לא היו לי בנים, שנאמר (לעיל כט ו) והנה רחל בתו באה עם הצאן, אפשר יש לו בנים והוא שולח בתו אצל הרועים, ועכשיו היו לו בנים שנאמר (להלן לא א) וישמע את דברי בני לבן:
@76 **נקבה שכרך.** כתרגומו פריש אגרך:
@77 **ואת אשר היה מקנך אתי.** את חשבון מעוט מקנך שבא לידי מתחלה כמה היו:
@78 **לרגלי.** עם רגלי, בשביל ביאת רגלי באת אצלך הברכה, כמו (שמות יא ח) העם אשר ברגלך, (שופטים ח ה) לעם אשר ברגלי, הבאים עמי: **גם אנכי לביתי.** לצורך ביתי, עכשיו אין עושין לצרכי אלא בני וצריך אני להיות עושה גם אני עמהם לסמכן, וזהו גם:
@80 **נקד.** מנמר בחברבורות דקות, כמו נקדות, פוינטור''א בלע''ז : **טלוא.** לשון טלאים חברבורות רחבות: **חום.** שחום דומה לאדום, רו''ש בלע''ז [אדום] לשון משנה שחמתית ונמצאת לבנה, לענין התבואה: **והיה שכרי.** אותן שיולדו מכאן ולהבא נקדים וטלואים בעזים ושחומים בכשבים יהיו שלי ואותן שישנן עכשיו הפרש מהם והפקידם ביד בניך, שלא תאמר לי על הנלדים מעתה אלו היו שם מתחלה, ועוד שלא תאמר לי על ידי הזכרים שהן נקדים וטלואים תלדנה הנקבות דוגמתן מכאן ואלך:
@81 **וענתה בי** וגו' **.** אם תחשדני שאני נוטל משלך כלום, תענה בי צדקתי, כי תבא צדקתי ותעיד על שכרי לפניך, שלא תמצא בעדרי כי אם נקדים וטלואים, וכל שתמצא בהן שאינו נקוד או טלוא או חום בידוע שגנבתיו לך, ובגנבה הוא שרוי אצלי:
@82 **הן.** לשון הן, קבלת דברים: **לו יהי כדברך.** הלואי שתחפץ בכך:
@83 **ויסר.** לבן ביום ההוא וגו' : **התישים.** עזים זכרים: **כל אשר לבן בו.** כל אשר היתה בו חברבורית לבנה: **ויתן.** לבן ביד בניו:
@84 **הנותרת.** הרעועות שבהן החולות והעקרות, שאינן אלא שירים, אותן מסר לו:
@85 **מקל לבנה.** עץ הוא ושמו לבנה, כמה דתימא (הושע ד יג) תחת אלון ולבנה, ואומר אני הוא שקורין טרינבל''א בלע''ז שהוא לבן [צפצפה עצנית]: **לח.** כשהוא רטוב: **ולוז.** ועוד לקח מקל לוז, עץ שגדלין בו אגוזים דקים קולדר''א בלע''ז [אלסר]: **וערמון.** קשטיניי''ר בלע''ז [עץ ערמון]: **פצלות.** קלופים קלופים, שהיה עושהו מנמר: **מחשף הלבן.** גלוי לובן של מקל. כשהיה קולפו היה נראה ונגלה לובן שלו במקום הקלוף:
@86 **ויצג.** תרגומו ודעיץ, לשון תחיבה ונעיצה הוא בלשון ארמי, והרבה יש בתלמוד (שבת נ ב) דצה ושלפה, (חולין צג ב) דץ ביה מידי. דצה כמו דעצה, אלא שמקצר את לשונו: **ברהטים.** במרוצת המים, בבריכות העשויות בארץ, להשקות שם הצאן: **אשר תבאן** וגו' **ברהטים.** אשר תבאנה הצאן לשתות, שם הציג המקלות לנכח הצאן: **ויחמנה.** הבהמה רואה את המקלות והיא נרתעת לאחוריה, והזכר רובעה ויולדת כיוצא בו. ר' הושעיא אומר המים נעשין זרע במעיהן ולא היו צריכות לזכר, וזהו ויחמנה וגו' :
@87 **אל המקלות.** אל מראות המקלות: **עקדים.** משנים במקום עקידתן, הם קרסלי ידיהן ורגליהן:
@88 **והכשבים הפריד יעקב.** הנלדים עקדים נקדים הבדיל והפריד לעצמן ועשה אותן עדר עדר לבדו, והוליך אותו העדר העקוד לפני הצאן, ופני הצאן ההולכות אחריהם צופות אליהם, וזהו שנאמר ויתן פני הצאן אל עקוד, שהיו פני הצאן אל העקדים, ואל כל חום שמצא בצאן לבן: **וישת לו עדרים.** כמו שפרשתי:
@89 **המקשרות.** כתרגומו הבכירות ואין לו עד במקרא להוכיח עליו. ומנחם חברו עם (שמואל ב' טו לא) אחיתפל בקשרים, (שם טו י) ויהי הקשר אמיץ, אותן המתקשרות יחד למהר עבורן:
@90 **ובהעטיף.** לשון אחור, כתרגומו ובלקישות. ומנחם חברו עם (ישעיה ג כג) המחלצות והמעטפות, לשון עטיפת כסות, כלומר מתעטפות בעורן וצמרן ואינן מתאוות להתיחם על ידי הזכרים:
@91 **צאן רבות.** פרות ורבות יותר משאר צאן: **ושפחות ועבדים.** מוכר צאנו בדמים יקרים ולוקח לו כל אלה:
@92 **עשה.** כנס, כמו (ש''א יד מח) ויעש חיל ויך את עמלק:
@94 **שוב אל ארץ אבותיך.** ושם אהיה עמך, אבל בעודך מחבר לטמא אי אפשר להשרות שכינתי עליך:
@95 **ויקרא לרחל וללאה.** לרחל תחלה ואחר כך ללאה שהיא היתה עקרת הבית, שבשבילה נזדוג יעקב עם לבן, ואף בניה של לאה מודים בדבר, שהרי בעז ובית דינו משבט יהודה אומרים (רות ד יא) כרחל וכלאה אשר בנו שתיהם וגו' , הקדימו רחל ללאה:
@98 **עשרת מנים.** אין מונים פחות מעשרה: **מנים.** לשון סכום כלל החשבון, והן עשיריות, למדנו שהחליף תנאו מאה פעמים:
@101 **והנה העתודים.** אף על פי שהבדילם לבן כלם שלא יתעברו הצאן דוגמתן, היו המלאכים מביאין אותן מעדר המסור ביד בני לבן לעדר שביד יעקב: **וברדים.** כתרגומו ופציחין פיישי''ד בלע''ז [מנומש], חוט של לבן מקיף את גופו סביב, חברבורית שלו פתוחה ומפולשת מזן אל זן, ואין לי להביא עד מן המקרא:
@104 **האל בית אל.** כמו אל בית אל, הה''א יתרה, ודרך מקראות לדבר כן, כמו (במדבר לד ב) כי אתם באים אל הארץ כנען: **משחת שם.** לשון רבוי וגדלה כשנמשח למלכות, כך (לעיל כח יח) ויצק שמן על ראשה, להיות משוחה למזבח: **אשר נדרת לי.** וצריך אתה לשלמו, שאמרת (שם כב) יהיה בית אלהים, שתקריב שם קרבנות:
@105 **העוד לנו חלק.** למה נעכב על ידך מלשוב, כלום אנו מיחלות לירש בנכסי אבינו כלום בין הזכרים:
@106 **הלוא נכריות נחשבנו לו.** אפלו בשעה שדרך בני אדם לתת נדוניא לבנותיו בשעת נשואין, נהג עמנו כנכריות, כי מכרנו לך בשכר הפעלה: **את כספנו.** שעכב דמי שכר פעלתך:
@107 **כי כל העשר.** כי זה משמש בלשון אלא, כלומר משל אבינו אין לנו כלום אלא מה שהציל הקדוש ברוך הוא מאבינו שלנו הוא: **הציל.** לשון הפריש, וכן כל לשון הצלה שבמקרא לשון הפרשה, שמפרישו מן הרעה ומן האויב:
@108 **את בניו ואת נשיו.** הקדים זכרים לנקבות, ועשו הקדים נקבות לזכרים, שנאמר (לקמן לו ו) ויקח עשו את נשיו ואת בניו וגו' :
@109 **מקנה קנינו.** מה שקנה מצאנו עבדים ושפחות וגמלים וחמורים:
@110 **לגזז את צאנו.** שנתן ביד בניו דרך שלשת ימים בינו ובין יעקב: **ותגנב רחל את התרפים.** להפריש את אביה מעבודה זרה נתכונה:
@113 **ביום השלישי.** שהרי דרך שלשת ימים היה ביניהם:
@114 **את אחיו.** קרוביו: **דרך שבעת ימים.** כל אותן שלשה ימים שהלך המגיד להגיד ללבן הלך יעקב לדרכו. נמצא יעקב רחוק מלבן ששה ימים, ובשביעי השיגו לבן, למדנו שכל מה שהלך יעקב בשבעה ימים הלך לבן ביום אחד (שנאמר וירדוף אחריו דרך שבעת ימים, ולא נאמר וירדוף אחריו שבעת ימים) :
@115 **מטוב עד רע.** כל טובתן של רשעים רעה היא אצל הצדיקים:
@117 **כשביות חרב.** כל חיל הבא למלחמה קרוי חרב:
@118 **ותגנב אתי.** גנבת את דעתי:
@120 **יש לאל ידי.** יש כח וחיל בידי לעשות עמכם רע. וכל אל שהוא לשון קדש על שם עזוז ורוב אונים הוא:
@121 **נכספתה.** חמדת, והרבה יש במקרא (תהלים פד ג) נכספה וגם כלתה נפשי, (איוב יד טו) למעשה ידיך תכסף:
@122 **כי יראתי** וגו' **.** השיבו על ראשון ראשון, שאמר לו (פסוק כו) ותנהג את בנותי וגו' :
@123 **לא יחיה.** ומאותה קללה מתה רחל בדרך: **מה עמדי.** משלך:
@124 **באהל יעקב.** הוא אהל רחל, שהיה יעקב תדיר אצלה, וכן הוא אומר (להלן מו יט) בני רחל אשת יעקב, ובכלן לא נאמר אשת יעקב: **ויבא באהל רחל.** כשיצא מאהל לאה חזר לו לאהל רחל קודם שחפש באהל האמהות. וכל כך למה, לפי שהיה מכיר בה שהיא משמשנית:
@125 **בכר הגמל.** לשון כרים וכסתות כתרגומו בעביטא דגמלא, והיא מרדעת העשויה כמין כר ובעירובין (דף טז א) הקיפוה בעביטין, והן עביטי גמלים, בשטי''ל בלע''ז :
@127 **דלקת.** רדפת, כמו (איכה ד יט) על ההרים דלקנו, וכמו (ש''א יז נג) מדלק אחרי פלשתים:
@128 **ויוכיחו.** ויבררו עם מי הדין, אפרובי''ר בלע''ז :
@129 **לא שכלו.** לא הפילו עבורם, כמו (הושע ט יד) רחם משכיל, (איוב כא י) תפלט פרתו ולא תשכל: **ואילי צאנך.** מכאן אמרו איל בן יומו קרוי איל, שאם לא כן מה שבחו, אילים לא אכל אבל כבשים אכל, אם כן גזלן הוא:
@130 **טרפה.** על ידי ארי או זאב: **אנכי אחטנה.** לשון (שופטים כ טז) קולע באבן אל השערה ולא יחטא, (מ''א א כא) אני ובני שלמה חטאים, חסרים, אנכי אחסרנה, אם חסרה חסרה לי, שמידי תבקשנה: **אנכי אחטנה.** תרגומו דהות שגיא ממנינא שהיתה נפקדת ומחסרת, כמו (במדבר לא מט) ולא נפקד ממנו איש, תרגומו ולא שגא: **גנבתי יום וגנבתי לילה.** גנובת יום או גנובת לילה הכל שלמתי: **גנבתי.** כמו (איכה א א) רבתי בגוים שרתי במדינות, (ישעיה א כא) מלאתי משפט, (הושע י יא) אהבתי לדוש:
@131 **אכלני חרב.** לשון (דברים ד כד) אש אכלה: **וקרח.** כמו (תהלים קמז יז) משליך קרחו, תרגומו גלידא: **שנתי.** לשון שינה:
@132 **ותחלף את משכרתי.** היית משנה תנאי שבינינו מנקוד לטלוא ומעקדים לברדים:
@133 **ופחד יצחק.** לא רצה לומר אלהי יצחק, שאין הקדוש ברוך הוא מיחד שמו על הצדיקים בחייהם, ואף על פי שאמר לו בצאתו מבאר שבע (לעיל כח יג) אני ה' אלהי אברהם אביך ואלהי יצחק, בשביל שכהו עיניו והרי הוא כמת, יעקב נתירא לומר אלהי ואמר ופחד: **ויוכח.** לשון תוכחה הוא ולא לשון הוכחה:
@134 **מה אעשה לאלה.** איך תעלה על לבי להרע להן:
@135 **והיה לעד.** הקדוש ברוך הוא:
@137 **לאחיו.** הם בניו, שהיו לו אחים נגשים אליו לצרה ולמלחמה:
@138 **יגר שהדותא.** תרגומו של גלעד: **גלעד.** כמו גלעד:
@140 **והמצפה אשר אמר** וגו' **.** והמצפה אשר בהר הגלעד, כמו שכתוב (שופטים יא כט) ויעבר את מצפה גלעד. ולמה נקרא שמה מצפה, לפי שאמר כל אחד מהם לחברו יצף ה' ביני ובינך אם תעבור את הברית: **כי נסתר.** ולא נראה איש את רעהו:
@141 **בנתי בנתי.** שתי פעמים, אף בלהה וזלפה בנותיו היו מפלגש: **אם תענה את בנתי.** למנוע מהם עונת תשמיש:
@142 **יריתי.** כמו (שמות טו ד) ירה בים, כזה שהוא יורה חנית:
@143 **אם אני.** הרי אם משמש בלשון אשר, כמו (לעיל כד לג) עד אם דברתי דברי: **לרעה.** לרעה אי אתה עובר, אבל אתה עובר לפרקמטיא:
@144 **אלהי אברהם.** קדש: **ואלהי נחור.** חול: **אלהי אביהם.** חול:
@145 **ויזבח יעקב זבח.** שחט בהמות למשתה: **לאחיו.** לאוהביו שעם לבן: **לאכל לחם.** כל דבר מאכל קרוי לחם, כמו (דניאל ה א) עבד לחם רב, (ירמיה יא יט) נשחיתה עץ בלחמו:
@147 **ויפגעו בו מלאכי אלהים.** מלאכים של ארץ ישראל באו לקראתו ללוותו לארץ:
@148 **מחנים.** שתי מחנות, של חוצה לארץ שבאו עמו עד כאן, ושל ארץ ישראל שבאו לקראתו:

@3 **והנה סלם מצב ארצה וראשו מגיע השמימה והנה מלאכי אלהים עולים ויורדים בו** . הראהו בחלום הנבואה כי כל הנעשה בארץ נעשה על ידי המלאכים והכל בגזרת עליון עליהם כי מלאכי אלהים אשר שלח ה' להתהלך בארץ לא יעשו קטנה או גדולה עד שובם להתיצב על אדון כל הארץ לאמר לפניו התהלכנו בארץ והנה יושבת בשלוה או מלאה חרב ודם והוא יצוה עליהם לשוב לרדת בארץ ולעשות דברו והראהו כי הוא יתברך נצב על הסלם ומבטיחו ליעקב בהבטחה גדולה להודיע שהוא לא יהיה ביד המלאכים אבל יהיה חלק ה' ויהיה עמו תמיד כמו שאמר והנה אנכי עמך ושמרתיך בכל אשר תלך כי מעלתו גדולה משאר הצדיקים שנאמר בהם (תהלים צא יא) כי מלאכיו יצוה לך לשמרך בכל דרכיך ועל דעת רבי אליעזר הגדול (פרקי דר"א לה) היתה זאת המראה כענין בין הבתרים לאברם כי הראהו ממשלת ארבע מלכיות ומעלתם וירידתם וזה טעם "מלאכי אלהים" כמו שנאמר בדניאל (י כ יג) שר מלכות יון ושר מלכות פרס והבטיחו כי הוא יתעלה יהיה עמו בכל אשר ילך ביניהם וישמרנו ויצילנו מידם אמרו (שם בפדר"א) הראה לו הקב"ה ארבע מלכיות מושלן ואבדן הראהו שר מלכות בבל עולה שבעים עוקים ויורד והראהו שר מלכות מדי עולה חמישים ושנים עוקים ויורד והראהו שר מלכות יון עולה מאה ושמונים עוקים ויורד והראהו שר מלכות אדום עולה ואינו יורד אמר לו יעקב אך אל שאול תורד (ישעיהו יד טו) אמר לו הקב"ה אם תגביה כנשר וגו' (עובדיה א ד)
@8 **כי אם בית אלהים וזה שער השמים** . הוא בית המקדש שהוא שער לעלות משם התפלות והקרבנות לשמים וכתב רש"י אמר רבי אלעזר בשם ר' יוסי בן זמרא (ב"ר סט ה) הסולם הזה עומד בבאר שבע ושיפועו מגיע עד בית המקדש שבאר שבע עומד בדרומו של יהודה וירושלם בצפונו בגבול שבין יהודה ובנימין ובית אל היה בצפון של נחלת בנימין בגבול שבין בנימין ובין בני יוסף נמצא סולם רגליו בבאר שבע וראשו בבית אל מגיע שפועו כנגד ירושלם ושאמרו רבותינו (חולין צא) צדיק זה בא לבית מלוני ועוד אמרו (פסחים פח) יעקב קראו בית אל וזו לוז היא ולא ירושלם ומהיכן למדו לומר כן אני אומר שנעקר הר המוריה ובא לכאן וזו היא קפיצת הארץ האמורה בשחיטת חולין (חולין צא) שבא בית המקדש לקראתו עד בית אל וזהו ויפגע במקום ואם תאמר כשעבר יעקב אבינו על בית המקדש מדוע לא עכבוהו שם איהו לא יהב דעתיה להתפלל במקום שהתפללו אבותיו ומן השמים יעכבוהו איהו עד חרן אזל כדאמרינן בפרק גיד הנשה (שם) וקרא מסייע לן וילך חרנה כי מטא לחרן אמר אפשר עברתי על מקום שהתפללו בו אבותי ולא התפללתי בו יהב דעתיה למהדר וחזר עד בית אל קפצה ליה ארעא עד בית אל כל אלו דברי הרב ולא נראה לי כלל שאין קפיצת הארץ שהזכירו ביעקב אלא כאותה שאמרו באליעזר עבד אברהם שבא ביום אחד לחרן כמו שאמרו בסנהדרין (צה) שלשה קפצה להם הארץ אליעזר עבד אברהם ויעקב אבינו ואבישי בן צרויה ופירשו אליעזר עבד אברהם דכתיב (לעיל כד מב) ואבא היום אל העין למימרא דההוא יומא נפק יעקב דכתיב ויפגע במקום כי מטא לחרן אמר אפשר שעברתי על מקום שהתפללו אבותי ולא התפללתי בו כיון דהרהר בדעתיה למהדר קפצה ליה ארעא מיד ויפגע במקום הנה בפירוש אומרים שכיון שעלה בלבו בחרן לחזור קפצה לו הארץ ופגע במקום שהתפללו בו אבותיו לא שחזר לבית אל ולא שקפץ הר המוריה ובא לשם ובבראשית רבה (נט יא) עוד עשו שניהם שוים בקפיצה אמרו ויקם וילך אל ארם נהרים (לעיל כד י) בר יומו ואבא היום אל העין היום יצאתי והיום באתי וביעקב דרשו (ב"ר סח ח) כן וילך חרנה רבנין אמרין בר יומו ומה טעם שיקפוץ הר המוריה ויבא עד בית אל אחר שטרח יעקב לחזור מחרן ועד בית אל מהלך כמה ימים ועוד כי בית אל איננו סוף גבול ארץ ישראל מפאת חרן כי חרן ארץ קדם הוא ועוד שאין האמצעות נקרא שפוע הסולם ועוד מה טעם להיותו כנגד בית אל והאמצע איננו מורה על דבר יותר מכולו אבל מדרשים הללו ענין אחר להם אמרו שם בבראשית רבה (סח ה) אמר רבי הושעיה כבר כתיב (לעיל כח ז) וישמע יעקב אל אביו ואל אמו וילך פדנה ארם ומה תלמוד לומר ויצא יעקב מבאר שבע אלא אמר אבא בשעה שבקש לצאת לחוצה לארץ מהיכן הורשה לו לא מבאר שבע אף אני הריני הולך לבאר שבע אם נותן לי רשות הריני יוצא ואם לאו איני יוצא לפיכך הוצרך הכתוב לומר ויצא יעקב מבאר שבע וכוונת המדרש הזה כי הם סבורים שיעקב בחברון נתברך שהוא ארץ מגורי אביו ולשם חזר אליו שנאמר (להלן לה כז) ויבא יעקב אל יצחק אביו ממרא קרית הארבע היא חברון אשר גר שם אברהם ויצחק ואם כן הכתוב שאמר ויצא יעקב מבאר שבע כי כאשר צוהו אביו ללכת אל לבן הלך שם ליטול רשות והוא המקום שלן בו וראה מראות אלהים ונתן לו הרשות לצאת כמו שאמר ושמרתיך בכל אשר תלך והשיבותיך אל האדמה הזאת והסולם שראה לדעת רבי יוסי בן זימרא ראה שרגליו בבאר שבע במקום אשר הוא שוכב שם וסוף שיפועו שהוא ראש הסולם מגיע עד כנגד בית המקדש נסמך בשמים בפתח שהמלאכים נכנסים ויוצאים בו והשם הנכבד נצב עליו ולכן ידע שבאר שבע הוא שער השמים טוב לתפלה ובית המקדש בית אלהים ובבקר נשא יעקב רגליו מבאר שבע וילך חרנה בן יומו והיא קפיצת הדרך שלו זהו דעת רבי יוסי בן זימרא שאמר בבראשית רבה (סט ז) הסולם הזה עומד בבאר שבע ושיפועו מגיע עד בית המקדש שנאמר ויצא יעקב מבאר שבע ויירא ויאמר מה נורא המקום הזה
@8 "והאבן" - אשר שם מצבה לא במקום שכיבתו הקים אותם שהרי באר שבע איננו בית אל והוא בבית אל העמיד אותה ולשם חזר בשובו שנאמר (להלן לה א) קום עלה בית אל ועשה שם מזבח לאל הנראה אליך וגו' אבל הקים אותה כנגד השיפוע במקום שראש הסולם עומד שקרא אותו בית אלהים והיא עיר לוז ולדעתו של רבי יוסי בן זמרא לוז היא ירושלים שקראו בית אל ואפשר שיהיה כן לפי המקראות שבספר יהושע ובאמת שאיננו בית אל הסמוך לעי כי כן שם העיר ההיא לראשונה בימי אברהם וקודם לכן ורבי יהודה ברבי סימון חלק שם (בב"ר סט ז) על רבי יוסי בן זימרא ואמר הסולם הזה עומד בבית המקדש ושיפועו מגיע עד בית אל מאי טעמיה ויירא ויאמר מה נורא המקום הזה וגו' ויקרא שם המקום ההוא בית אל ודעת רבי יהודה ברבי סימון כי "ויפגע במקום" הוא הר המוריה וילן שם כי בא השמש לו בלא עתו שאמרו צדיק זה בא לבית מלוני ויפטר בלא לינה וראה הסולם רגליו במקום ההוא ושיפועו שהוא ראשו מגיע עד כנגד בית אל זה והיא עיר לוז ואמר כי זה המקום בית אלהים ושיפוע הסולם שער השמים והנה הר המוריה טוב לתפלה וגם בית אל מקום ראוי לעבוד שם האלהים והקים המצבה בבית אל כי לדעת כולם כנגד השיפוע הקים אותה ויסכים דעתו של רבי יהודה ברבי סימון עם המדרש שבגמרא בפרק גיד הנשה (חולין צא) ובפרק חלק (סנהדרין צה) שיעקב יצא מבאר שבע והלך לחרן וכשנמלך לחזור ולהתפלל במקום שהתפללו אבותיו בהר המוריה אז קפצה לו הארץ ויפגע מיד בהר המוריה ושמא דעתם שקפצה לו בהליכה ובחזרה כדברי האומר (בב"ר סח ח) וילך חרנה בן יומו ויפגע במקום מיד בפתע פתאום ומצאתי עוד מפורש בפרקי רבי אליעזר הגדול (פרק לה) אמר בן שבעים ושבע שנה היה יעקב בצאתו מבית אביו והיתה הבאר מהלכת לפניו מבאר שבע ועד הר המוריה מהלך שני ימים והגיע לשם בחצי היום וכו' אמר לו הקב"ה יעקב הלחם בצקלונך והבאר לפניך לאכול ולשתות ולשכב במקום הזה אמר לפניו רבון כל העולמים עד עכשיו יש לשמש ירידות מעלות חמשים ואני שוכב במקום הזה ובלא עתו בא השמש ממערב והביט יעקב וראה את השמש בא במערב וילן שם כי בא השמש לקח יעקב שתים עשרה אבנים מאבני המזבח שנעקד עליו יצחק אביו ושם אותם מראשותיו להודיעו שעתידין לעמוד ממנו שנים עשר שבטים ונעשו כלן אבן אחת להודיעו שכלן עתידים להיות גוי אחד בארץ שנאמר ( ז כג) ומי כעמך ישראל גוי אחד השכים יעקב בבקר בפחד גדול ואמר ביתו של הקב"ה במקום הזה שנאמר ויירא ויאמר מה נורא המקום מכאן אתה למד שכל המתפלל בירושלם כאלו מתפלל לפני כסא הכבוד ששער שמים הוא פתוח לשמוע תפלתן של ישראל שנאמר וזה שער השמים ושב יעקב ללקט האבנים ומצא אותן כלן אבן אחת ושם אותה מצבה בתוך המקום וירד לו שמן מן השמים ויצק עליה שנאמר ויצוק שמן על ראשה מה עשה הקב"ה נטל רגל ימינו וטבע את האבן עד עמקי תהומות ועשה אותה סניף לארץ כאדם שהוא נותן סניף לכיפה לפיכך נקראת אבן שתיה ששם הוא טבור הארץ ומשם נפתחה הארץ ועליה היכל ה' עומד שנאמר והאבן הזאת אשר שמתי מצבה יהיה בית אלהים ומשם נשא רגליו וכהרף עין בא לחרן עד כאן והנה המדרשים כולם אף על פי שיש ביניהם חלוף במקצת אבל כלם מודים שקפיצת הארץ היתה ליעקב שהלך מהלך כמה ימים כהרף עין ויתכן שכלם מודים זה לזה ובכל הליכותיו קפצה לו בלכתו מבאר שבע לחרן וברצותו לשוב להר המוריה ובצאתו משם לחרן ואין אחד מכל המדרשים שיאמר כדברי רש"י
@9 **וישם אותה מצבה** . כבר פירשו רבותינו (ע"ז נג) ההפרש שבין המצבה למזבח שהמצבה אבן אחת והמזבח אבנים הרבה ונראה עוד שהמצבה תעשה לנסך עליה נסך יין וליצוק עליה שמן לא לעולה ולא לזבח והמזבח להעלות עליו עולות ושלמים ובבאם לארץ נאסרה עליהם המצבה (דברים טז כב) מפני ששמו אותה הכנענים להם לחק יותר מן המזבחות אף על פי שכתוב בהם (שמות לד יג) את מזבחותם תתוצון או שלא רצה לאסור הכל והשאיר המזבח שראוי לנסך ולקרבנות
@11 **אם יהיה אלהים עמדי** . לשון רש"י אם ישמור לי הבטחות הללו שהבטיחני וטעם התנאי שלא יגרום החטא וכך אמרו בבראשית רבה (עו ב) רב הונא בשם ר' אחא הנה אנכי עמך וכתיב אם יהיה אלהים עמדי אלא מכאן שאין הבטחה לצדיקים בעולם הזה ויתכן עוד על דרך הפשט שאין הספק בדבר אבל בכל העתיד יאמר הכתוב כן כמו עד אשר אם עשיתי וכן ואם יהיה היובל לבני ישראל (במדבר לו ד) אם יבא העת שיהיה התנאי אז יתקיים המעשה כלומר בבואו
@12 **והיה ה' לי לאלהים** . איננו תנאי כדברי רש"י אבל הוא נדר וענינו אם אשוב אל בית אבי אעבוד השם המיוחד בארץ הנבחרת במקום האבן הזאת שתהיה לי לבית אלהים ושם אוציא את המעשר ויש בענין סוד ממה שאמרו (כתובות קי) כל הדר בחוצה לארץ דומה כמי שאין לו אלוה
@15 **וירא והנה באר בשדה והנה שם שלשה עדרי צאן רובצים עליה** . יאריך הכתוב בספור הזה להודיענו כי קווי ה' יחליפו כח ויראתו תתן עוז כי הנה יעקב אבינו בא מן הדרך והוא עיף ויגל לבדו האבן אשר היו צריכים אליה כל הרועים ושלשה עדרי צאן אשר להם רועים רבים ושומרים כלם רובצים עליה אינם יכולים להניעה כלל ולרבותינו בבראשית רבה (ע ח) גם בזה להם סוד רמז לעתיד כי נזדמן לו ככה שנכנס בדרך הבאר ולא נאספו כל העדרים רק שלשה מהם ובא בזמן שהאבן על פי הבאר והעדרים שומרים לה וכל הענין המסופר כאן להודיעו שיצליח בדרך הזה ויצא ממנו זרע זוכה לרמז הזה כי הבאר ירמוז לבית המקדש וג' עדרי צאן עולי שלשה רגלים כי מן הבאר ההוא ישקו העדרים שמשם היו שואבין רוח הקדש או שירמוז כי מציון תצא תורה (ישעיהו ב ג) שנמשלה למים (ב"ק יז) ודבר ה' מירושלם ונאספו שמה כל העדרים באים מלבא חמת עד נחל מצרים (מלכים א ח סה) וגללו את האבן והשקו שמשם היו שואבין רוח הקודש והשיבו את האבן מונח לרגל הבא
@18 **הידעתם את לבן בן נחור** . היה ניכר וידוע בשם אבי אביו כי הוא נכבד מאביו וראש בית אבותם כדכתיב (להלן לא נג) אלהי אברהם ואלהי נחור ויתכן שהיה בתואל אדם פחות מעלה ולא ירצה לבן שייחסו אותו האנשים רק לאבי אביו כי כן מצאנו (לעיל כד נ) ויען לבן ובתואל אולי היה כל זה למעלת אברהם כי היו כל המשפחה מתייחסים לנחור אחי אברהם
@22 **וטעם כי רועה היא** . להגיד כי אין לצאן לבן רועה אחר זולתה כי לה לבדה מסר אביה העדר והיא לבדה רועה אותם כל הימים לא תלך בהם לאה אחותה כלל ולא היה ענינה כבנות יתרו שהיו שבע בנותיו כולן רועות כאחת כמו שאמר ותבאנה ותדלנה (שמות ב טז) ואולי בעבור כי עיני לאה רכות היה השמש מזיק לה או בעבור שהיתה לאה גדולה ראויה לאיש וחשש לה אביה אבל יתרו נכבד במקומו וכהן הארץ ויראו מגשת אל בנותיו או שהיה לבן צנוע ממנו כי משפחת אברהם כשרה וצנועה ורחל היתה קטנה ואין לחוש לה וזה ענין וישק יעקב לרחל או הוא כדברי רבי אברהם (לעיל כז כה) כי נשיקה בלמ"ד איננה בפה רק נשק אותה על ראשה או על כתיפה
@25 **ותגד לאביה** . לשון רש"י אמה מתה וכך בבראשית רבה (ע יג) ולפי פשוטו לבשרו ביאת קרובו ושיצא אליו ויכבדהו כי אמה מה לה ומה תעשה לו אבל רבקה הראת את אמה התכשיטין אשר נתנו לה כמנהג הנערות
@28 **הכי אחי אתה ועבדתני חנם** . לא סיפר הכתוב שהיה יעקב עובד אותו ויתכן כי מעת שאמר וישק את צאן לבן אחי אמו לא יצא הצאן מידו כי בראותו את רחל כי רועה היא חמל עליה שלא תשוב לרעות צאן עוד והיה הוא רועה אותן באהבתו אותה ואפשר עוד לומר כי לבן דבר בערמה אמר לו מתחלה כי עצמו ובשרו הוא ויחמול עליו כאשר יחמול האדם על עצמו ועל בשרו וכאשר ראה שהיה יעקב מתעכב שם מתפרנס מאשר ללבן אמר לו הכי אחי אתה ותעבדני חנם כי ידעתי כי מעתה תעבוד אותי כי איש מוסר אתה ולא תתפרנס משל אחרים וגם אני איני רוצה שתהיה העבודה שתעבדני בחנם בלא משכורת שלימה והגידה לי מה תבקש אתה במשכורתך ואתן אז הכיר יעקב דעתו ואמר לו שיעבוד אותו ז' שנים ברחל והעבודה מן הסתם היא מרעה הצאן כי לה היו צריכים ובה היו מדברים
@34 **כי מלאו ימי** . שאמרה לי אמי ועוד כי מלאו ימי הריני בן פ"ד שנה ואימתי אעמיד י"ב שבטים לשון רש"י מלא שבוע זאת דבק הוא בחטף שבוע של זאת והן ז' ימי המשתה גם זה לשון רש"י ואם כן למה לא פירש הרב מלאו ימי על שני העבודה והתנאי ששלמו כדברי אונקלוס והוא משמעות הכתוב באמת ובשביל הימים שאמרה לו אמו גם מפני זקנתו לא יתן לו לבן בתו קודם זמנו אשר התנו שניהם ודי שיקיים תנאו וכדברי אונקלוס הוא שנצטרך לפרש מלא שבוע זאת על ימי המשתה כי ימי העבודה שלמים היו כאשר אמר לו יעקב וכן פירש רבי אברהם ואני לא ידעתי כי שבעת ימי המשתה תקנת משה רבינו לישראל (ירושלמי כתובות פ"א ה"א) ואולי נאמר שנהגו בהם מתחלה נכבדי האומות כענין באבילות דכתיב (להלן נ י) ויעש לאביו אבל שבעת ימים ומה שלמדו כאן בירושלמי (מו"ק פ"א ה"ז) ובבראשית רבה (ע יט) שאין מערבין שמחה בשמחה סמך בעלמא ממנהגי הקדמונים קודם התורה אבל בגמרא שלנו (מו"ק ט) לא למדוה מכאן ודרשוה מויעש שלמה את החג (מלכים א ח סה) ויתכן לומר כי היה זה מחלוף משכורתו עשרת מונים (להלן לא מא) כי יעקב אמר לו מתחלה כי מלאו הימים ולבן שתק ונתן לו לאה ואחר כן אמר לו לבן מלא שבוע זאת כי עדיין לא מלאו ימי עבודת לאה וקודם זמני נתתיה לך ויעקב שמע אליו וימלא אותם כדברי לבן כי מה יוכל לעשות והוא ברחל יחפוץ ולכן לא אמר הכתוב בתחילה "ויהי במלאת הימים ויאמר יעקב וגו'" ועוד יתכן לומר כי כאשר היה בשנה השביעית אמר יעקב ללבן הבה את אשתי כי מלאו ימי שזו שנת מלאת הימים וכן זקן עם מלא ימים (ירמיהו ו יא) הוא אשר הגיעו לשנת סופו וכן עד יום מלאת ימי מלואיכם (ויקרא ח לג) עד יום השביעי שבו ימלאו ימי המלואים או שאמר "מלאו" בעבור שהיו קרובים להמלא וחשובים כמלאים וכמוהו רבים וכן בסדר האחר (להלן לה יח) בצאת נפשה כי מתה בהיותה קרובה לכך וחשובה כאילו מתה וזה טעם ואבואה אליה כלומר לא שתתן אותה ואלכה אבל שאשאנה ואשלים מעט הימים אשר עלי כי מעתה לא תירא ממני שאעזבך ורבותינו עשו מדרש (ב"ר ע יח) בלשון "ואבואה אליה" בעבור שאיננו דרך מוסר להזכיר כן אף כי בצדיקים אבל הכוונה היא מה שאמרתי ואחרי כן אמר לו לבן מלא שבוע השנים של לאה זאת כי אולי בעבור שעברתי על דעתך לא תשלים אותן או כדי שיהיה ידוע מתי התחילו ימי עבודת רחל ואז אתן לך האחרת בעבודה אשר תעבוד עמדי לאחר הנישואין
@40 **ונתנה לך** . לשון רבים נרדה ונבלה שם (לעיל יא ז) ונשרפה (שם פסוק ג) אף זה לשון ונתן זה פירש"י ולא אמר למה יתפוס היחיד לשון הרבים אולי יחשוב שהוא דרך הנכבדים בלשון הקדש כמאמר אחרים (ראה ראב"ע לעיל א כו) ורבי אברהם אמר בכאן (שם) שהוא בנין נפעל והו"ו השיבו לעתיד ופירושו ותנתן לך והנכון בעיני כי דברי לבן בערמה אמר ליעקב לא יעשה כן במקומנו כי לא יניחוני אנשי המקום לעשות כן כי נבלה הוא אצלם אבל תמלא שבוע זאת ונתן לך אני וכל אנשי המקום גם את זאת שכלנו נסכים בדבר ונעשה לך כבוד ומשתה כאשר עשינו בראשונה
@43 **ויאהב גם את רחל** . הזכיר הכתוב שגם אהב רחל יותר מלאה והטעם בעבור כי הטבע לאהוב יותר האשה אשר ידע האדם בראשונה כענין שהזכירו חכמים בנשים (סנהדרין כב) ואינה כורתת ברית אלא למי שעשאה כלי והנה יעקב אהב רחל מלאה שלא כדרך הארץ וזה טעם "גם"
@44 **כי שנואה לאה** . הנה לאה רמתה באחותה גם ביעקב כי אם נאמר שנהגה כבוד באביה שאחז בה והכניסה אליו ואל תמר בו היה לה להגיד או לרמוז כי היא לאה אף כי היתה מתנכרת כל הלילה ולפיכך לא הכירה עד שראה אותה בבקר ולכן שנאה יעקב והאלהים יודע כי להנשא אל הצדיק עשתה כן ורחם עליה וכך אמרו בבראשית רבה (עא ב) כיון שראה יעקב מעשים שרמתה לאה באחותה נתן דעתו לגרשה וכיון שפקדה הקב"ה בבנים אמר לאמן של אלו אני מגרש וזה טעם "וירא אלהים" כי חמל עליה שלא יעזבנה ויש אומרים (הרד"ק) כי שתים נשים שהאחת אהובה מאד תקרא השניה שנואה כנגדה כמו שאמר ויאהב גם את רחל מלאה לא ששנאה והיתה בושה בדבר וראה אלהים את עניה
@49 **הבה לי בנים** . אמרו המפרשים (רש"י וראב"ע) שתתפלל עלי ואם אין מתה אנכי לשון רש"י שמי שאין לו בנים חשוב כמת והוא מדרש רבותינו (ב"ר עא ו) ואני תמה אם כן למה חרה אפו ולמה אמר התחת אלהים אנכי ושומע אל צדיקים ה' ומה שאמר אבא לא היו לו בנים אני יש לי בנים ממך מנע ממני לא מנע וכי הצדיקים אינן מתפללים בעד אחרים והנה אליהו ואלישע התפללו בעד נשים נכריות (מ"א יז כא ושם ב ד טז) ונראה שבשביל זה תפסוהו רבותינו אמרו בבראשית רבה (עא ז) אמר לו הקב"ה כך עונין את המעיקות חייך שבניך עתידין לעמוד לפני בנה ועל דרך הפשט אמרה רחל ליעקב שיתן לה בנים ובאמת דעתה לאמר שיתפלל עליה אבל שיתפלל עליה עד שיתן לה בנים על כל פנים ואם אין שתמית עצמה בצער דברה שלא כהוגן בקנאתה וחשבה כי באהבתו אותה יתענה יעקב וילבש שק ואפר ויתפלל עד שיהיו לה בנים שלא תמות בצערה ויחר אף יעקב שאין תפלת הצדיקים בידם שתשמע ותענה על כל פנים ובעבור שדברה דרך געגועי הנשים האהובות להפחידו במיתתה חרה אפו ולכך אמר לה שאינו במקום אלהים שיפקוד העקרות על כל פנים ואיננו חושש בדבר כי ממנה נמנע פרי הבטן ולא ממנו וזה ליסר אותה ולהכלימה והנה הצדקת בראותה שלא תוכל להסמך על תפלת יעקב שבה להתפלל על עצמה אל שומע צעקה וזהו וישמע אליה אלהים (להלן פסוק כב) ואולי נתקן על דעת רבותינו כי יעקב אי אפשר שלא נתפלל על אשתו האהובה כי עקרה היא אלא שלא נתקבלה תפלתו ובאה עתה רחל להתעולל עליו לאמר שיתן לה בנים על כל פנים בתפלתו כי לא נופל הוא מאביו שעשה כן ויחר אפו ואמר לה כי הדבר ביד אלהים ולא בידו ואביו נשמעה תפלתו שהוא צדיק ועתיד להיות לו זרע אבל היא נמנע ממנה פרי בטן ונכון הוא
@53 **ותלד ליעקב בן** . הזכיר בכל השפחות "ליעקב" להגיד כי הוא חפץ ומודה בהם ואיננו נקרא לו בן האמה רק בן ליעקב כבני הגבירות המתיחסים אליו ואמר בלאה בן חמישי ובן ששי ליעקב בעבור רבוי הבנים לומר כי בכולן יחפוץ ואת כולם יקרב ולא הזכיר בראשונים כן
@57 **ותרא לאה כי עמדה מלדת** . לא ידעתי מה המעשה הזה ללאה ולמה נתנה שפחתה לבעלה והיא לא היתה עקרה שתבנה ממנה ואין דרך הנשים להרבות נשים לבעליהן אבל נצטרך לומר כי היו נביאות (ב"ר עב ו) יודעות שעתיד יעקב להעמיד י"ב שבטים ורצתה שיהיו לו רוב הבנים ממנה או משפחתה שהיא ברשותה ולא תתגבר אחותה עליה בבנים ולכך אמרה נתן אלהים שכרי אשר נתתי שפחתי לאישי (ראה זוהר ויצא קנז) וכן יעקב בעבור זה שמע אליה שיעמיד בנים רבים כי ידע כן כדברי רבותינו (ב"ר סח יא) ויתכן כי מדעתם שנתנה הארץ לזרעם ואברהם ויצחק לא הרבו בנים היה חפץ יעקב בנשים רבות להרבות זרעו לנחול את הארץ כי דור רביעי ישובו הנה ולכן רצתה ליתן לו שפחתה שלא ישא נכרית
@62 **דודאים** . סיגלי (סנהדרין צט) ובלשון ישמעאל יאסמין כך מצאתי בפירוש רש"י ואינו כן כי יאסמין בלשון ערבי כך שמו בדברי רבותינו כדאמרינן בפרק במה טומנין (שבת נ) האי כוספא דיאסמין שרי וסיגלי אומרים שהם "כנפסגא" שאמרו בהן (ברכות מג) מברכין עליהם בורא עשבי בשמים אבל אין זמנם בימי קציר חטים אולי מצאם שם במקרה והראוי לקבל בדודאים דעת אונקלוס שתרגם בהן יברוחין ובבראשית רבה (עב ב) גם כן ר' חייא ב"ר אבא אמר יברוחין והן יברוח בלשון ערבי וכתב רבי אברהם דודאים אמר המתרגם יברוחין וכך יקראו בלשון ישמעאל ויש להן ריח טוב וכן כתוב (שיר השירים ז יד) הדודאים נתנו ריח והם על צורת בן אדם כי יש להן דמות ראש וידים ויש אומרים כי יועילו להריון ואנכי לא ידעתי בעבור שתולדתם קרה אלו דבריו והנכון כי רצתה בהן להשתעשע ולהתענג בריחן כי בתפלה נפקדה רחל לא בדרך הרפואות וראובן הביא ענפי הדודאים או הפרי והוא כדמות תפוחים ולהם ריח טוב אבל השרש והוא העשוי בצורת ראש וידים לא הביא והשרש הוא שאומרים עליו האנשים שיועיל להריון ואם הדבר אמת הוא בסגולה בהם לא בטבעם אבל לא ראיתי כן באחד מספרי הרפואות המדברים בהם
@63 **המעט קחתך את אישי** . הטעם המעט ממך שתקחי לך את אישי כאילו את אשתו ואני האמה אף כי תעשי עצמך גברת לקחת הדודאים אשר אני מתענגת בריחן ויתכן שרצתה בהן לכבוד יעקב לבשם בהם יצועיו כי דרך נשים לה כענין שכתוב (משלי ז יז) נפתי משכבי מר ואהלות וקנמון ולכן אמרה לאה המעט קחתך את אישי ממני אף כי תקחי דודאי בני לפתותו בהם ויש אומרים הדודאים עשבים יוסיפו התאוה לנשים נגזר מלשון עת דודים (יחזקאל טז ח) ולכן אמרה לאה המעט קחתך את אישי כאשר הזכרתי
@68 **זבדני אלהים אותי זבד טוב** . לא מצאו למלה הזאת מוצא בלשון הקדש ויתכן שנאמר שהיא מלה מורכבת "זה בד" כמלת מדוע ומלת בגד (לעיל פסוק יא) בכתיבה והסגול והפתח מומרים במקומות רבים וכל שכן במלות המורכבות וכן מלת צלמות ומלת בלעדי ויצאה מלשון בדים בדי עצי שטים (שמות כה יג) ותעש בדים ותשלח פארות (יחזקאל יז ו) כי ענפי האילן הגסים נקראים כן והשאילוה לבנים יאכל בדיו בכור מות (איוב יח יג) לא כן בדיו (ישעיהו טז ו) ולכן אמרה לאה כי עשה לה האלהים זה הבן בד טוב להיות בעלה מתלונן בצלה כי יזבלני בצלי וכן בנה בניתי בית זבול לך (מלכים א ח יג) להתלונן בצלו ולכבוד עליון יאמר כן כמו שאמר (שם בפסוק כז) הנה השמים ושמי השמים לא יכלכלוך אף כי הבית הזה אשר בניתי וכן שמש ירח עמד זבולה (חבקוק ג יא) עמד במקום שיתלונן בו כמו שאמר לשמש שם אהל בהם (תהלים יט ה) ואונקלוס תרגם זבד טוב "חולק טב" ולא הבינותי סברתו עד שראיתי (בתרגום הירושלמי) בתרגום יונתן זווד יתי מימרא דה' זוודין טבין ולמדתי שעשו המלה כאלו כתובה בו"ו וטפלו אותה אל לשון הארמית שמתרגמין צדה "זוודין" (להלן מב כה) אמרה שהבן הזה עשאו השם לה צדה טובה וחלק טוב כי בעלה יהיה עיקר דירתו עמה לרוב בניה תתפרנס עמו בטוב לו והו"ו והבי"ת ישתוו בלשוננו במקומות רבים כמו תאוה ותאבה (תהלים קיט כ) גוי נתתי למכים (ישעיהו נ ו) על גבי חרשו חורשים (תהלים קכט ג) וכן לקצבי הרים ירדתי (יונה ב ז) כמו לקצוי וכן לפרבר למערב ארבעה (דברי הימים א כו יח) יאמרו ממנו פרוור דכתיב (מלכים ב כג יא) אל לשכת נתן מלך הסריס אשר בפרוורים ופירוש שניהם מה שהוא מקיר החומה לחוצה ומגרש לערים (במדבר לה ב) תרגום ירושלמי ופרוור וכן תרגום יונתן מגרשות (יחזקאל כז כח) ובמשנה מלא תרווד תרבד (נזיר מט אהלות פ"ב מ"א) בטבלא שאין לה לבזביז (פסחים מח) במקומות שונין ממנו "לזביז" (כלים פ"ב מ"ג מקואות פ"ד מ"ב) ובמקומות שונין ממנו "לזויז" איצטבא (פסחים יא) "איצטוא" (עירובין עז ויומא מט לפי גירסת הערוך) וכן כיוצא בהן הרבה ונהגו בירושלמי (כלאים פ"ה הכ"ט יבמות פ"ז ה"ח ועוד) "אביר" בבי"ת במקום ו"ו שאינם מקפידים בכך
@71 **אסף אלהים את חרפתי** . הכניסה במקום שלא תראה וכן ולא יאסף הביתה (שמות ט יט) וכוכבים אספו נגהם (יואל ב י) וירחך לא יאסף (ישעיהו ס כ) לא יטמן לשון רש"י ורבי אברהם אמר כטעם כרת ונאספה שמחה וגיל והנכון דעת אונקלוס שעשאן כולן לשון קבוץ וכנוס כפשוטם מלשון ויאספו את השליו (במדבר יא לב) כי מאספיו יאכלוהו (ישעיהו סב ט) ונקראת המיתה אסיפה בהיותו נקבץ אל אבותיו המתים ולא יאסף הביתה להקבץ לאנשי ביתו ואספו נגהם שקבצו האור בתוכם ולא הוציאו אורם לחוץ או שנאספו אל האהל אשר להם ברקיע השמים ויאמרו אסיפה בחרפה שתתקבץ ולא תתפזר בין בני אדם להיות נדברים בה עוד בחוצות
@75 **נחשתי ויברכני ה' בגללך** . בעבורך ובזכותך כי איש צדיק אתה ולשון נחשתי נסיתי וכל נחש נסיון ויש אומרים (ראב"ע) שהיה מנחש בתרפים ויעקב אמר ויברך ה' אותך לרגלי לא רצה לומר "בגללי" דרך ענוה ואמר לרגלי כי מעת שבא רגלי בבית היית מתברך
@77 **ואת אשר היה מקנך אתי** . את חשבון מיעוט מקנך שבא לידי כמה היה לשון רש"י כלומר אתה ידעת כמה היה מקנך כשבאו אתי ויותר ראוי שיאמר ואת מקנך אשר היה אתי ידעת כי מעט אשר היה לך טרם בואי ויפרוץ לרוב או נפרש אתה ידעת את אשר עבדתיך כי בכל כחי עשיתי וידעת את אשר היה מקנך אתי כי ימים רבים הם וידעת כי מעט אשר היה לך לפני ויפרוץ לרוב שלא כדרך כל הארץ רק ברכת ה' היא אשר באה מעת בא רגלי בביתך והוא הנכון
@78 **אעשה גם אנכי לביתי** . עכשיו אין עושין לצרכי אלא בני וצריך אני להיות עושה עמהם לסומכן וזהו גם לשון רש"י ולא מצאנו שיהיה ליעקב צאן ולא שירעו אותן בניו הקטנים והגדול שבהם בן שש שנים או פחות כי לבן יתכן שהיו לו בנים קטנים מרחל בטרם בא יעקב ועתה הם ראויים לרעות הצאן ואולי על נשיו ועל עבדיו אמר שהיו עושים לו במלאכה ואין כל זה נכון אבל פירוש מתי אעשה גם אנכי לביתי מתי אעשה אנכי גם לביתי כאשר עשיתי גם לביתך וכן ויאהב גם את רחל מלאה (לעיל כט ל) וגם אהב את רחל מלאה וכן גם אותכה הרגתי (במדבר כב לג) גם הרגתי אותך ורבים כן
@80 **וטעם נקוד וטלוא** . נקוד או טלוא וכל שה חום פירשו בו (הראב"ע והרד"ק) שחור כי השחרות מפני החום ואיננו נכון בעיני כי רוב הכשבים שחורים אף כי בארץ קדם שהיא חמה ואם כן יהיו כולם ליעקב והנכון דעת אונקלוס "שחום" והוא קרוב לאדום וקורין אותו רו"ש וכן פרש"י ויהיה חום מגזרת ואור החמה (ישעיהו ל כו) שהוא דומה לשמש אשר יתאדם קצת
@80 "והיה שכרי" - לשון רש"י אותן שילדו מכאן ולהבא נקודים וטלואים בעזים ושחומים בכשבים יהיו שלי וכן דעת רבי אברהם (בפסוק לה) ופירוש כל שה נקוד וטלוא תיש וטלוא ונקוד בעזים הנקבות כמו שאמר (שם) ויסר ביום ההוא את התישים ואת כל העזים ופירוש כל אשר לבן בו בנזכרים וכל חום בכשבים ולפי דעתי כי כל נקוד וטלוא בכשבים וכל חום בהם היה שכרו שהרי לא עשה במקלות מראה חום והיה מפסיד שכרו מן הכשבים שהם מיטב הצאן וכן בחלומו הראוהו העולים על הצאן עקודים נקודים אין בהם חום ופירוש הכתוב הסר משם כל שה נקוד וטלוא וכל חום בכשבים והסר טלוא ונקוד בעזים והיה שכרי שלשת המראות בכשבים והשנים בעזים ואמר
@80 "וענתה בי צדקתי ביום מחר" - כי כל אשר איננו נקוד וטלוא בעזים וגם חום בכשבים גנוב הוא אתי
@83 **וטעם ויסר ביום ההוא את התישים** . סיפר הכתוב כי יעקב אמר סתם הסר משם טלוא ונקוד בעזים ולבן חשש לזרע האב והפריש הזכרים והנקבות והפריש אפילו העקודים אשר להם לובן מעט ברגליהם במקום העקידה והפריש בכשבים כל אשר לבן בו וכל חום ואם יהיה "כל אשר לבן בו" לומר שהפריש בתישים ובעזים כל אשר בו מראה לבן בין עקוד בין ברוד יהיה וכל חום מוסף על המראות הנזכרות וטעם הוסיפו בשכר הכשבים חום מפני שאין בתולדתם להיותם בעלי גוונין כתישים והעזים ואין בתולדת העזים להיות בהן חום
@85 **ויקח לו יעקב מקל לבנה** . כיון שהסכימו להיות שכרו באלה היה רשאי לעשות כל מה שיוכל להולידם כן ואולי התנה יעקב שיעשה בהן כל מה שירצה כי לבן לא היה יודע בתולדה הזו והרועים לא היו מרגישים בדבר בראותם המקלות ברהטים פעם אחת בשנה בימי ניסן כי בהעטיף הצאן בימי תשרי לא ישים שלא ישאר ללבן עד פרסה ויש אומרים (הרד"ק) כי השנה הראשונה נולדו ליעקב נקודים וטלואים רבים בברכת השם אשר הראה לו המלאך ושם המקלות בפני אלו שהיו שלו שיולידו בדמותם שלא יאמר לבן כאשר יולדו כי גנוב הוא אתו וזה פירוש בכל יחם הצאן המקושרות שהם הנולדים לו ובהעטיף הצאן של לבן לא ישים והיה העטופים ללבן אשר לא יולדו נקודים והקשורים כלם ליעקב כי יולדו נקודים
@88 **והכשבים הפריד יעקב** . פירש רש"י הנולדים עקודים נקודים הבדילם לעצמם ועשה אותן עדר לבד והוליך אותו העדר העקוד לפני הצאן ופני הצאן ההולכות אחריהן צופות באלו וזהו שאמר ויתן פני הצאן אל עקוד שהיו פני הצאן אל עקוד ואל כל חום שנמצא בצאן לבן וישת לו עדרים לבדו ולא שתם על צאן לבן כמו שפירשתי זה לשון הרב ואין דבריו בכאן נכונים כי למה הפריד הכשבים ולא נשאר בעדר לבן נקוד או חום לא בכשבים ולא בעזים ואם היו הנפרדים אותם אשר הולידו הצאן עקודים נקודים וטלואים שהיו שלו ומהם עשה העדר הזה העקוד למה הפריד הכשבים לבדם ולא לקח גם התישים והעזים שנולדו לו כן ויעשה מכלם העדר העקוד הזה אשר הוליך לפני הצאן ועוד שלא אמר שנולד שם חום ועוד כי לפי דעת הרב אין בכשבים עקוד וטלוא שאינם שכרו ולא עשה להם מקלות אבל פירוש הכתוב שהפריד הכשבים מן העזים ועשה מהן עדר מיוחד והנה היו לו עדר כשבים ועדר עזים ונתן פני כל הצאן עדר הכשבים ועדר העזים אל העקודים ואל כל חום אשר בכל צאן לבן ששם העקודים לפני העזים וכל חום לפני הכשבים על דעת הראשונים או העקודים וכל חום לפני הכשבים על דעתנו כי צורך ההפרדה מפני החום אשר היה שכרו בכשבים לבדן והנכון בעיני שיאמר כי הכשבים הפריד יעקב ונתן פני הצאן הנזכר שהם הכשבים אל עקוד ואל כל חום וישת לו עדרים לבדו מן העקוד והחום והוליכם לפני הכשבים ולא שתם על צאן לבן כי היו שכרו וטעם בצאן לבן שעשה כן בכל צאן לבן והנה העקוד בכשבים היו שלו ואל תשאל למה אמר "הכשבים" ואמר "פני הצאן" כי דרך מקראות לדבר כן ובפרשה הזאת בדומה לו בהר הגלעד (להלן לא כא) וטעם עשותו כן בכשבים מפני שלא היה במקלות חום או שידע בתולדת הכשבים שצריכים לסימנים רבים בכבדותם יותר מן התישים לקלותם
@89 **הצאן המקושרות** . הנכון בעיני בלשון הזה שהם הצאן אשר הזכרים מהם הולכים אחר הנקבות בכל עת לא יתפרדו מהם לרב תאותם מלשון ונפשו קשורה בנפשו (להלן מד ל) ולשון חכמים כן הוא (בכורות כד) חזיר כרוך אחר רחל בכרוכין אחריה (קדושין עט) ויקראו הנולדים בעת ההיא "הקשורים" על שם אביהם ורבים אמרו כי קשורים הם החזקים אשר איבריהם קשורים זה בזה קשר אמיץ כי זה סיבת הבריאות והעטופים הם החלושים אשר נפשם בהם תתעטף ואין להם תאוה מלשון העטופים ברעב (איכה ב יט) והתרגום אמר בכיריא ולקישיא כי כן הדבר
@97 **כי בכל כחי עבדתי את אביכן** . מתחילה ונתברך לרגלי ויתכן שהיה ללבן צאן רבות כי נתברכו גם העטופים לרגל יעקב כי לא צעקו בניו רק בקנאתם ליעקב שעשה כל הכבוד הזה
@98 **ואביכן התל בי והחליף את משכורתי** . זה היה אמת ואם לא ספרו הכתוב מתחלה וכן אמר לו ותחלף את משכורתי עשרת מונים (להלן פסוק מא) וכזה במקומות רבים בתורה ובפרשה הזאת למעלה לא ספר שנתנה לאה את הדודאים לרחל
@99 **וטעם אם כה יאמר נקודים יהיה שכרך** . כי מתחילה נתן לו שני המראות נקודים וטלואים גם החום בכשבים וחזר בו לתת מראה אחד והיה מחליף אותו בכל שנה והיו הצאן יולדות כן ולא היה זה במקלות כי הוא מספר להם מעשה השם הגדול שעשה עמו להפליא מדי שנה בשנה כאשר אמר ולא נתנו אלהים להרע עמדי גם יתכן שהיה מחליף את משכורתו אחרי שהיו הצאן מעוברות והיו יולדות כרצון יעקב כאשר ישר בעיני היוצר לעשות ובבראשית רבה (עד ג) צפה הקב"ה מה שלבן עתיד לעשות ליעקב אבינו והוא צר צורה כיוצא בה אם כה אמר אין כתוב כאן אלא אם כה יאמר
@101 **ויהי בעת יחם הצאן** . זה היה אחר שהחליף את משכורתו ולכך אמר כי ראיתי את כל אשר לבן עושה לך וטעם והנה העתודים העולים על הצאן הראה לו בחלום כי יעלו על הצאן העתודים וכולם עקודים ואחרי כן היו כולם נקודים ושוב היו כולם ברודים והגיד כי הוא רואה החמס שעושה לו לבן להחליף את משכורתו ויעשה הנולדים כמראה אשר יצטרך אליו יעקב ומכאן ואילך לא יעשה יעקב מקלות כי בוטח בה' ישוגב (משלי כט כה)
@101 "והנה העתודים העולים על הצאן" - התישים והאילים יקראו עתודים כי כל גדול בצאן יקרא כן אף בגדולי האנשים כל עתודי ארץ (ישעיהו יד ט) וכתב רש"י אף על פי שהבדילם לבן כולם שלא יתעברו הצאן דוגמתן היו המלאכים מביאים אותן מעדר המסור לבני לבן לעדר שביד יעקב ועל דרך הפשט היה זה מראה להבטיחו כי יולידו כהם והעד מלת "והנה" כי בכל החלום יאמר כן (לעיל כח יב יג להלן מ ט טז) בטעם כאילו הדבר לפניו ובבראשית רבה (עד ג) לא הזכירו המלאכים אלא ממדרש אמרו עולים אין כתוב כאן אלא העולים כי פשוטו של מקרא כמו שאמרנו
@104 **אנכי האל בית אל** . יספר יעקב לנשיו כל מה שאמר לו מלאך האלהים בחלום כי הכל פיוס להם שתלכנה עמו אבל מה שיספר לא חלום אחד הוא כי מאמר "שא נא עיניך וראה כל העתודים" היה בהיותו עובד את לבן בצאנו בעת יחם הצאן באחת מהשנים הראשונות ומאמר "אנכי האל בית אל" היה אחר כן בעת הנסיעה כי אחר שאמר לו קום צא מן הארץ הזאת לא נתעכב עוד בחרן לרעות עוד צאן לבן ויעלו התישים על הצאן ותלדנה נקודים וטלואים רק ממחרת החלום שלח לרחל וללאה ויספר להם חלומו והלכו להם וטעם אנכי האל בית אל פירש"י ה"א יתירה והוא כמו אנכי אל בית אל וכמהו (במדבר לד ב) אל הארץ כנען ובעלי הלשון (הראב"ע והרד"ק) תקנו אנכי האל אל בית אל וכן ומעץ הדעת טוב ורע (לעיל ב ט) העבותות הזהב (שמות לט יז) והמלאך ידבר בלשון שולחו ועל דרך האמת יאמר המלאך הזה אנכי האל בית אל וכן ויקרא למקום אל בית אל (להלן לה ז) כמו שאמר ציון קדוש ישראל (ישעיהו ס יד) ויונתן בן עוזיאל אמר (שם ו ג) קדיש בשמי מרומא עילאה בית שכינתיה והוא המלאך הגואל (להלן מח טז) וכן בכל ביתי נאמן הוא (במדבר יב ז) והמשכיל יבין וטעם אשר משחת שם מצבה אשר נדרת לי שם נדר כי אתה נדרת להיות עובד לשם המיוחד בארץ הנבחרת ולהיות לך האבן בית אלהים ולהוציא שם מעשרותיך ואם תאחר נדריך עוד יקצוף האלהים על קולך
@110 **ותגנוב רחל את התרפים** . לא נתכוונה אלא להפריש אביה מעבודה זרה לשון רש"י ואפשר כי היו ללבן לעבודה זרה כאשר אמר למה גנבת את אלהי אבל לא היו כל התרפים נעבדים כי איך תמצא עבודה זרה בבית אדונינו דוד (עיין שמואל א יט יג) והקרוב מה שאומרים שהם כלים לקבל השעות ויקסמו בהם לדעת עתידות והמלה נגזרת מלשון רפה ידים (שם ב יז ב) נרפים אתם נרפים (שמות ה יז) יקראו אותם "תרפים" לרמוז בשמם כי דבורם כמו נבואה רפה תבא ברב ותכזב לעתים רחוקות כמו שאמרו (זכריה י ב) כי התרפים דברו און והנה יעשו אותם קטני אמנה להם לאלהים לא ישאלו בשם הנכבד ולא יתפללו אליו רק כל מעשיהם בקסמים אשר יגידו להם התרפים וכתוב (שופטים יז ה) והאיש מיכה לו בית אלהים ויעש אפוד ותרפים ושם כתוב (יח ה) שאל נא באלהים ונדעה התצליח דרכינו כי בתרפים היו שואלים וכן היה הענין בישראל באפוד כי אחרי אשר הורגלו באפוד הקדש עשו כדמותו והיו שואלים בו ומאמינים בדבריו ותועים אחריו גם בחלים לא ידרשו את ה' כי אם בהם וזה טעם ויעש אותו גדעון לאפוד ויצג אותו בעירו בעפרה ויזנו כל ישראל אחריו שם ויהי לגדעון ולביתו למוקש (שופטים ח כז) כי סרו מאחרי ה' והנה לבן היה קוסם ומנחש כאשר אמר (לעיל ל כז) נחשתי וארצו ארץ קוסמים מעולם כדכתיב (ישעיהו ב ו) כי מלאו מקדם ועוננים כפלשתים ובלעם בן בעור הקוסם היה מעירו וזה טעם למה גנבת את אלהי
@113 **ביום השלישי** . שהרי דרך ג' ימים היה ביניהם דרך שבעת ימים כל אותן ג' ימים הלך המגיד להגיד את לבן שהלך יעקב לדרכו נמצא רחוק מלבן ששה ימים ובשביעי השיגו ולמדנו שכל מה שהלך יעקב בששה ימים הלך לבן ביום אחד לשון רש"י מבראשית רבה (עד ו) ונכון הוא שילך לבן כגבור לרוץ ארח כי כן דרך הרודפים אבל לבן דרך שלשה ימים שם בין צאנו ובין הצאן אשר ביד יעקב לא בין העיר ובין צאנו כאלו לבן רועה צאנו במזרח לעיר יעקב למערבה וביניהם דרך שלשת ימים והנה יעקב מן העיר נסע כי שם ביתו בניו ובנותיו וכל אשר לו מלבד הצאן והוגד ללבן ביום השלישי כי לא הרגישו ביום הראשון ושב לבן לעירו ולקח את אחיו משם ורדף אחריו מעירו שבעה ימים והשיגו ביום השביעי אבל נאמר על דעת בראשית רבה כי מן השדה אשר שם הצאן נסע יעקב ולבן לקח את אחיו עמו מגוזזי צאנו ובפרקי רבי אליעזר (פרק לו) נראה כי לבן שב לעירו ומשם לקח כל גבור וכל בן חיל ורדף אחריו משם
@114 **וידבק אותו בהר הגלעד** . כי ביום השביעי בערב הגיע לבן אל תחת ההר וראה את יעקב חונה עליו מרחוק ולן בלילה ההוא למטה ויבא אליו החלום
@115 **וטעם אל לבן הארמי** . להגיד כי אף על פי שהוא ארמי ואנשי מקומו אנשי תרפים ועוננים כפלשתים (ישעיהו ב ו) בא אליו חלום הנבואה לכבוד הצדיק וכן ויגנב יעקב את לב לבן הארמי אף על פי שהוא הארמי הקוסם בעל התרפים
@115 "מטוב עד רע" - כל טובתן של רשעים רעה היא אצל הצדיקים לשון רש"י ופשוטו השמר לך פן תדבר עמו לעשות לו טובה אם ישוב עמך מדרכו או פן תפחידנו לעשות לו רעה אם לא יבא עמך כי אני צויתיו לשוב אל ארצו
@124 **באהל יעקב ובאהל לאה** . כתב רש"י באהל יעקב הוא אהל רחל שהיה תדיר אצלה וכן הוא אומר בני רחל אשת יעקב ובכלן לא נאמר אשת יעקב ויבא באהל רחל כשיצא מאהל לאה חזר לו לאהל רחל קודם שיחפש באהל האמהות וכל כך למה שהיה מכיר בה שהיא ממשמשנית ועל דרך הפשט איננו נכון שיקראנו בפסוק אחד בשני שמות ורבי אברהם אמר שבא באהל יעקב ובאהל לאה ובאהל שתי האמהות כי אהל אחד לשתיהן ואחר כך שב שנית אל אהל לאה ואחרי כן אל אהל רחל וגם זה איננו נכון ועוד כתב והקרוב אלי שהכתוב אחז דרך קצרה ואיחר להזכיר אהל רחל להזכיר בכלן "ולא מצא" כי לא היו שם וחזר ופירש כי בעת צאתו מאהל לאה בא באהל רחל אשר שם התרפים והוא הנכון אבל כי אהלים היו לכולם כי היה זה מצניעות הצדיק כי לכל אחת מארבע הנשים היה אהל מיוחד בעבור שלא תדע האחרת בבאו אל רעותה גם אסור הוא בדין תורה כמו שהזכירו חכמים במסכת נדה (יז) וליעקב אהל מיוחד ושם תאכלנה על שולחנו עם בניו ועם בני ביתו וטעם "אשת יעקב" שהזכיר ברחל על דעתי כפשוטו בעבור שהיא מוזכרת בין הפילגשים בפרשה ההיא (להלן מו יט) ולכן לא אמר כן בסדר וישלח יעקב (לה כד) שימנה לאה ורחל ואחרי כן השפחות
@126 **אל יחר בעיני אדני כי לא אוכל לקום מפניך** . לא הבינותי מה התנצלות זה וכי הנשים אשר להם האורח לא יקומו ולא יעמודו אולי אמרה כי ראשה ואבריה כבדים עליה והיא חולה בבא הארח כי כן דרכן וכל שכן במעטות הלידה כרחל שדמיהן מועטין והארח יכבד עליהם מאד והנכון בעיני כי היו הנדות בימי הקדמונים מרוחקות מאד כי כן שמן מעולם "נדות" לריחוקן כי לא יתקרבו אל אדם ולא ידברו בו כי ידעו הקדמונים בחכמתם שהבלן מזיק גם מבטן מוליד גנאי ועושה רושם רע כאשר בארו הפילוסופים עוד אני עתיד להזכיר נסיונם בזה (ויקרא יח יט) והיו יושבות בדד באהל לא יכנס בו אדם וכמו שהזכירו רבותינו בברייתא של מסכת נדה תלמיד אסור לשאול בשלמה של נדה רבי נחמיה אומר אפילו הדבור היוצא מפיה הוא טמא אמר רבי יוחנן אסור לאדם להלך אחר הנדה ולדרוס את עפרה שהוא טמא כמת כך עפרה של נדה טמא ואסור ליהנות ממעשה ידיה ולכך אמרה רחל ראויה הייתי לקום מפני אדוני לנשק ידיו אבל דרך נשים לי ולא אוכל להתקרב אליך וגם לא ללכת באהל כלל שלא תדרוך אתה עפר רגלי והוא החריש ממנה ולא ענה אותה כי לא היו מספרים עמהן כלל מפני שדבורה טמא
@127 **ויחר ליעקב וירב בלבן** . מתחילה נתן לו רשות לחפש כי אמר עם אשר תמצא את אלהיך ואמר נגד אחינו הכר לך מה עמדי ואיך ימצא אם לא יחפש וימשש אבל מתחלה היה חושש אולי אחת הנשים או העבדים גנבו את אלהיו ועתה בראותו כי אינם עמהם חרה אפו כי אמר לא אבד את אלהיו רק תואנה הוא מבקש ממני אמר לו למה דלקת אחרי כאשר ירדוף האדם אחרי הגנב הנה לא מצאת עמי מכל כלי ביתך דבר והיה ראוי לי לקחת ממך כל מה שאוכל כי אתה החלפת את משכורתי עשרת מונים והיית תובע ממני הטרפות ושלמתי לך שלא כדין
@133 **ופחד יצחק היה לי** . לא רצה לומר אלהי יצחק לפי שאין הקב"ה מיחד שמו על הצדיקים בחייהם ואף על פי שאמר לו בצאתו (לעיל כח יג) אני ה' אלהי אברהם אביך ואלהי יצחק בשביל שכהו עיניו והרי הוא כמת נתיירא יעקב לומר לשון רש"י וכן דעת אונקלוס כי פחד יצחק אלהיו דדחיל ליה יצחק ורבי אברהם אמר יראת יצחק את השם הועילתני כי זכות האב תועיל לבן וישבע יעקב בפחד אביו יצחק (פסוק נג) במי שיצחק מתפחד ממנו והנה אין פירושו שוה עוד כתב (שם) ויש אומרים כי זה הפחד רמז ליום העקדה ואיננו רחוק ועל דרך האמת יבא הלשון כפשוטו ומשמעו והוא מדת הדין של מעלה וממנו אמר הכתוב (הושע ג ה) אחר ישובו בני ישראל ובקשו את ה' אלהיהם ואת דוד מלכם ופחדו אל ה' ואל טובו באחרית הימים יאמר כי יבקשו הרחמים ומדת הדין שלמטה ויביאו פחד יצחק אל השם ואל טובו הנזכרים
@133 "ויוכח אמש" - לשון תוכחה ולא לשון הוכחה לשון רש"י ויותר נכון לשון הוכחה כי אמר למעלה ויוכיחו בין שנינו ואמר עתה כי האלהים היודע הנסתרות הוא הוכיח בין שניהם ולכך לא אמר "ויוכח אותך אמש"
@134 **ולבנותי מה אעשה לאלה היום** . אמרו (הראב"ע והרד"ק) שהוא כמו ולבנותי מה אעשה להן היום והיא תוספת ביאור וכן אשר נשבענו שנינו אנחנו (שמואל א כ מב) בנינו ובנותינו אנחנו (נחמיה ה ב) ויותר נכון נראה שהוא דרך חמלה ולבנותי מה אעשה לאלה אשר לפני כי נכמרו רחמי עליהן או לבניהן הנולדים בביתי והם לי כבני וזה טעם אשר ילדו ואמר זה כמתנצל על דברי יעקב כי באתי אחריך לראות בנותי ומה אוכל לעשות להם טובה או לבניהם ועתה אטיב להן שתכרות לי ברית שלא תענה אותן ולא תקח עליהן נשים
@135 **והיה לעד** . הקב"ה לשון רש"י ואיננו כמשמעו אבל יאמר והיה הברית לעד בינותינו כי העובר עליו יקולל בכל אלות הברית כטעם והיו בך לאות ולמופת (דברים כח מו) או טעמו נכרתה ברית בדבר קיים שיהיה לעד בינותינו על כן הרים יעקב אבן והוא מה שאמר עד הגל הזה ועדה המצבה כטעם ויאמר יהושע הנה האבן הזאת תהיה בנו לעדה (יהושע כד כז)
@137 **ויאמר יעקב לאחיו** . לאחי לבן הנזכר אשר באו עמו כי לא רצה לאמר כן לחמיו שהיה נוהג בו כבוד וכן ויקרא לאחיו לאכל לחם לאחי לבן ולא קרא ללבן דרך כבוד כאלו הכל ברשותו והכל שלו ודומה להם ויאמר פרעה לאחיו מה מעשיכם (להלן מז ג) ורש"י פירש לאחיו של יעקב כי הבאים עם לבן אוהביו ורעיו הם ויתכן כי מה שאמר בלבן ויקח את אחיו עמו (לעיל פסוק כג) הם קרוביו בני משפחתו מזרע נחור אחי אברהם ועשה כן בעבור שלא ירצה להביא על יעקב אנשים נכרים שלא יריבו עמו בכח או יחמדו ויגזלו ויגנבו מאשר לו והנה אלה קרובים ליעקב כמו ללבן על כן יקראו אחים לשניהם ויש אומרים (פסיקתא זוטרתא לעיל כט ד) שאמר להם אחי דרך מוסר כמו שאמר לרועים (שם) אחי מאין אתם ובבראשית רבה (עד יג) אמרו ויאמר יעקב לאחיו אלו בניו שהיה קורא אותן בלשון כבוד אחיו אבל בויקרא לאחיו לאכל לחם לא פירש והנכון מה שכתבתי תחילה
@137 "ויאכלו שם על הגל" - אכלו שם מעט לזכרון או שהוא דרך הבאים בברית לאכול שניהם מלחם אחד לאהבה ולחברה ואחרי בואם בשבועה ובברית זבח להם זבח ועשה להם כרה גדולה ויתכן כי טעם ויאכלו שם על הגל הזבח הנזכר למטה כי אמר להם לקטו אבנים ונעשה גל לאכול עליו ויהיה עד בבואנו בברית ואחרי כן אכלו עליו זבח וטעם ויאכלו לחם שעשה להם סעודה גדולה ללון עמו לא משתה בלבד
@139 **ויאמר לבן הגל הזה עד** . אחרי שקראו יעקב גלעד דבר לבן בלשון יעקב הגל הזה עד ועל כן נקרא שמו גלעד כי בשם הזה הסכימו שניהם או שדברי לבן מתורגמין ללשון הקדש
@140 **וטעם והמצפה** . כתב רש"י והמצפה אשר בהר גלעד כמו שכתוב (שופטים יא כט) ויעבור את מצפה גלעד למה נקראת מצפה אשר אמר כל אחד מהם לחבירו יצף ה' ואם כן הוא שם מקום גבוה בראש ההר ולפי דעתי שהיא האבן שהקים יעקב מצבה והוא נמשך על כן קרא שמו גלעד והמצפה קרא כי אמר יצף ה' ואפשר שהוא מצפה גלעד (עיין שופטים יא כט) שהמקום יקרא על שם האבן הזאת לעולם
@147 **ויפגעו בו מלאכי אלהים** . לשון רש"י מלאכי ארץ ישראל יצאו לקראתו מחנים שתי מחנות של חוצה לארץ באו עמו עד כאן ושל ארץ ישראל יצאו לקראתו ואני תמה בזה שהרי עדיין לא הגיע יעקב לארץ ורחוק היה משם ושלח מלאכים אל עשו מרחוק ושם (להלן לב כג) נאמר ויעבור את מעבר יבק שהוא "יבק הנחל גבול בני עמון" (דברים ג טז) שהוא דרומית מזרחית לארץ ישראל ועדיין יש לו לעבור גבול בני עמון ומואב ואחרי כך ארץ אדום ותחלת ביאתו בארץ בשכם היה שנאמר (להלן לג יח) ויבא יעקב שלם עיר שכם אשר בארץ כנען אבל היתה המראה הזאת ליעקב כאשר בא בגבול אויביו להודיעו כי רבים אשר אתו מאשר אתם ונקרא שם המקום מחנים כי כן הדרך בשמות או מחנים מחנהו ומחנה העליונים לומר כי מחנהו בארץ כמחנה המלאכים כלם מחנות אלהים מברכים לו ומודים בייחודו יתברך שמו לעולמים חסלת פרשת ויצא נכתבה הפרשה הזאת להודיע כי הציל הקב"ה את עבדו וגאלו מיד חזק ממנו וישלח מלאך ויצילהו וללמדנו עוד שהוא לא בטח בצדקתו והשתדל בהצלה בכל יכלתו ויש בה עוד רמז לדורות כי כל אשר אירע לאבינו עם עשו אחיו יארע לנו תמיד עם בני עשו וראוי לנו לאחז בדרכו של צדיק שנזמין עצמנו לשלשת הדברים שהזמין הוא את עצמו לתפלה ולדורון ולהצלה בדרך מלחמה לברוח ולהנצל וכבר ראו רבותינו הרמז הזה מן הפרשה הזאת כאשר אזכיר (להלן לב ט לג טו)
